import React, { useState, useCallback, useEffect } from 'react';
import { TreeNode, ChatMessage, NodeType, HistoryStep } from './types';
import DiagnosticTreeNodeComponent from './components/DiagnosticTreeNodeComponent';
import ChatPanel from './components/ChatPanel';
import LegendComponent from './components/LegendComponent';
import LanguageSelector from './components/LanguageSelector';
import TutorialModal from './components/TutorialModal';
import { getAiExplanation } from './services/geminiService';
import { translationsEN, DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID_EN } from './i18n/en';
import { translationsES, DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID_ES } from './i18n/es';

// Helper icon components
const TreeIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 2.25H2.25A2.25 2.25 0 0 0 0 4.5v15A2.25 2.25 0 0 0 2.25 21.75h15a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75V6.75A2.25 2.25 0 0 0 16.5 4.5h-6.75a2.25 2.25 0 0 0-2.25 2.25v6.75a2.25 2.25 0 0 0 2.25 2.25h6.75a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75h-1.5m1.5 0v-1.5m0 1.5L12 9m3 3L12 9m0 0L9 12m3-3v1.5m0 0H9m3.75-3.75L12 6.75m0 0L10.125 5.25M12 6.75V5.25m0 1.5L13.875 5.25m-3.75 0h.008v.008h-.008V5.25Z" />
  </svg>
);

const ChatBubbleIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 12a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0H8.25m4.125 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0H12m4.125 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0h-.375M21 12c0 4.556-3.86 8.25-8.625 8.25S3.75 16.556 3.75 12 7.61 3.75 12.375 3.75 21 7.444 21 12Z" />
  </svg>
);

type Language = 'en' | 'es';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language | null>(null);
  const [showTutorial, setShowTutorial] = useState(false);
  const [appReady, setAppReady] = useState(false);

  const [currentNodeId, setCurrentNodeId] = useState<string>('');
  const [history, setHistory] = useState<HistoryStep[]>([]);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState<boolean>(false);
  const [isChatPanelOpen, setIsChatPanelOpen] = useState<boolean>(false);

  const { t, DIAGNOSTIC_TREE_DATA, INITIAL_NODE_ID } = lang === 'es' 
    ? { t: translationsES, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID: INITIAL_NODE_ID_ES }
    : { t: translationsEN, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID: INITIAL_NODE_ID_EN };

  useEffect(() => {
    if (lang) {
      setCurrentNodeId(INITIAL_NODE_ID);
      const hasSeenTutorial = localStorage.getItem('hasSeenTutorial');
      if (!hasSeenTutorial) {
        setShowTutorial(true);
      } else {
        setAppReady(true);
      }
    }
  }, [lang, INITIAL_NODE_ID]);

  const handleSelectLanguage = (selectedLang: Language) => {
    setLang(selectedLang);
  };

  const handleCloseTutorial = () => {
    setShowTutorial(false);
    localStorage.setItem('hasSeenTutorial', 'true');
    setAppReady(true);
  };

  const currentNode = DIAGNOSTIC_TREE_DATA[currentNodeId];

  const navigateToNode = useCallback((nodeId: string | undefined, answerGiven?: 'Yes' | 'No') => {
    if (nodeId && DIAGNOSTIC_TREE_DATA[nodeId]) {
      const currentFullNode = DIAGNOSTIC_TREE_DATA[currentNodeId];
      if (!currentFullNode) return; 

      const newHistoryStep: HistoryStep = {
        nodeId: currentNodeId,
        nodeText: currentFullNode.text,
        nodeType: currentFullNode.type,
      };
      if (currentFullNode.type === NodeType.QUESTION || currentFullNode.type === NodeType.REASSESSMENT) {
        newHistoryStep.answer = answerGiven;
      }

      setHistory(prev => [...prev, newHistoryStep]);
      setCurrentNodeId(nodeId);
    }
  }, [currentNodeId, DIAGNOSTIC_TREE_DATA]);

  const handleBack = useCallback(() => {
    if (history.length > 0) {
      const lastStep = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setCurrentNodeId(lastStep.nodeId);
    }
  }, [history]);

  const handleRestart = useCallback(() => {
    setHistory([]);
    setCurrentNodeId(INITIAL_NODE_ID);
    setChatMessages([]); 
  }, [INITIAL_NODE_ID]);

  const handleExport = useCallback(() => {
    const reportDate = new Date().toLocaleString();
    let content = `${t.appTitle}\n${"=".repeat(t.appTitle.length)}\n\n`;
    content += `${lang === 'es' ? 'Fecha' : 'Date'}: ${reportDate}\n`;
    content += `${lang === 'es' ? 'Idioma' : 'Language'}: ${lang === 'es' ? 'Español' : 'English'}\n\n`;

    content += `${t.path.summary}\n${"-".repeat(t.path.summary.length)}\n\n`;

    history.forEach((step, index) => {
      const nodeData = DIAGNOSTIC_TREE_DATA[step.nodeId];
      content += `[${index + 1}] (${step.nodeId}) ${step.nodeText}\n`;
      if (step.answer) {
        content += `    ${t.path.answerHeader}: ${step.answer === 'Yes' ? t.path.yes : t.path.no}\n`;
      }
      if (nodeData?.details) {
        content += `    Context: ${nodeData.details}\n`;
      }
      content += `\n`;
    });

    if (currentNode) {
       content += `\n${lang === 'es' ? 'NODO ACTUAL / FINAL' : 'CURRENT / FINAL NODE'}:\n${"-".repeat(25)}\n`;
       content += `ID: ${currentNode.id}\n`;
       content += `Type: ${t.nodeTypes[currentNode.type.toLowerCase()]}\n`;
       content += `Text: ${currentNode.text}\n`;
       if (currentNode.details) {
         content += `Details: ${currentNode.details}\n`;
       }
    }

    content += `\n\n${t.footer}\n`;

    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${t.node.exportFilename || 'Diagnostic_Report'}_${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, [history, currentNode, DIAGNOSTIC_TREE_DATA, t, lang]);

  const handleUserMessage = useCallback(async (userQuery: string) => {
    if (!userQuery.trim() || !lang) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString() + 'user',
      sender: 'user',
      text: userQuery,
      timestamp: new Date(),
    };
    setChatMessages(prev => [...prev, userMessage]);
    setIsChatLoading(true);

    try {
      const aiResponseText = await getAiExplanation(userQuery, currentNode, lang);
      const aiMessage: ChatMessage = {
        id: Date.now().toString() + 'ai',
        sender: 'ai',
        text: aiResponseText,
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      console.error("Error getting AI explanation:", error);
      const errorMessage: ChatMessage = {
        id: Date.now().toString() + 'error',
        sender: 'ai',
        text: t.chat.error,
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsChatLoading(false);
    }
  }, [currentNode, lang, t]);

  if (!lang) {
    return <LanguageSelector onSelectLanguage={handleSelectLanguage} />;
  }

  if (!appReady) {
    return (
      <>
        <TutorialModal isOpen={showTutorial} onClose={handleCloseTutorial} t={t} />
        <div className="min-h-screen bg-gradient-to-br from-black via-slate-900 to-teal-900" />
      </>
    );
  }

  if (!currentNode) {
    return <div className="p-4 text-red-400 bg-slate-900 min-h-screen">Error: Node not found.</div>;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-slate-900 to-teal-900 flex flex-col items-center p-4 selection:bg-teal-500 selection:text-white">
      <TutorialModal isOpen={showTutorial} onClose={handleCloseTutorial} t={t} />
      <header className="w-full max-w-5xl mb-6 text-center">
        <div className="flex items-center justify-center space-x-3 mb-2">
           <TreeIcon className="w-12 h-12 text-teal-400" />
          <h1 className="text-4xl font-bold text-stone-100">{t.appTitle}</h1>
        </div>
        <p className="text-lg text-teal-300">{t.appSubtitle}</p>
      </header>

      <div className="w-full max-w-5xl flex flex-col lg:flex-row gap-6">
        {/* Diagnostic Tree Panel */}
        <main className="flex-grow lg:w-2/3 bg-slate-800 p-6 rounded-xl shadow-2xl border border-teal-700">
          <DiagnosticTreeNodeComponent
            node={currentNode}
            history={history}
            onNavigate={navigateToNode}
            onBack={handleBack}
            onRestart={handleRestart}
            onExport={handleExport}
            canGoBack={history.length > 0}
            t={t}
          />
          <LegendComponent t={t} />
        </main>

        {/* Chat Panel Toggle for Mobile/Small Screens */}
         <button
          onClick={() => setIsChatPanelOpen(!isChatPanelOpen)}
          className="lg:hidden fixed bottom-4 right-4 bg-teal-600 text-white p-3 rounded-full shadow-lg z-50 hover:bg-teal-700 transition-colors"
          aria-label={t.chat.toggle}
        >
          <ChatBubbleIcon className="w-6 h-6" />
        </button>

        {/* Chat Panel - Conditional rendering for mobile, always visible for lg+ */}
        <aside 
          className={`
            fixed inset-0 bg-slate-800 bg-opacity-95 backdrop-blur-sm z-40 p-4 transform transition-transform 
            ${isChatPanelOpen ? 'translate-x-0' : 'translate-x-full'} 
            lg:relative lg:translate-x-0 lg:inset-auto lg:z-auto lg:p-0 lg:bg-transparent lg:backdrop-blur-none
            lg:w-1/3 
          `}
        >
