import React, { useState, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticTreeNodeProps {
  node: TreeNode;
  history: HistoryStep[];
  onNavigate: (nodeId: string | undefined, answerGiven?: 'Yes' | 'No') => void;
  onBack: () => void;
  onRestart: () => void;
  onExport: () => void;
  canGoBack: boolean;
  t: any; // Translation object
}

const getNodeStyling = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return {
        bgColor: 'bg-slate-700',
        borderColor: 'border-teal-600',
        textColor: 'text-slate-200',
        titleColor: 'text-teal-400',
        icon: '❓', 
        contextBgColor: 'bg-slate-600'
      };
    case NodeType.ALERT:
      return {
        bgColor: 'bg-red-900/60', // Darker red with opacity
        borderColor: 'border-red-500',
        textColor: 'text-red-300',
        titleColor: 'text-red-400',
        icon: '❗',
        contextBgColor: 'bg-red-800/60'
      };
    case NodeType.INTERVENTION:
      return {
        bgColor: 'bg-sky-900/60', // Darker sky blue with opacity
        borderColor: 'border-sky-500',
        textColor: 'text-sky-300',
        titleColor: 'text-sky-400',
        icon: '💡', 
        contextBgColor: 'bg-sky-800/60'
      };
    case NodeType.OUTCOME:
      return {
        bgColor: 'bg-neutral-700',
        borderColor: 'border-neutral-500',
        textColor: 'text-neutral-200',
        titleColor: 'text-neutral-100',
        icon: '🏁', 
        contextBgColor: 'bg-neutral-600'
      };
    default: // Should not happen with defined types
      return {
        bgColor: 'bg-slate-600',
        borderColor: 'border-slate-400',
        textColor: 'text-slate-100',
        titleColor: 'text-slate-300',
        icon: 'ℹ️',
        contextBgColor: 'bg-slate-500'
      };
  }
};

const PathSummaryTable: React.FC<{ history: HistoryStep[], t: any }> = ({ history, t }) => {
  const decisions = history.filter(
    (step) => (step.nodeType === NodeType.QUESTION || step.nodeType === NodeType.REASSESSMENT) && step.answer
  );

  if (decisions.length === 0) {
    return null;
  }

  return (
    <div className="mt-6 mb-4 p-4 border border-slate-600 rounded-lg bg-slate-700 shadow-md">
      <h3 className="text-md font-semibold text-slate-100 mb-3">{t.path.summary}</h3>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-500">
          <thead className="bg-slate-800">
            <tr>
              <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-slate-400 uppercase tracking-wider">
                {t.path.questionHeader}
              </th>
              <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-slate-400 uppercase tracking-wider">
                {t.path.answerHeader}
              </th>
            </tr>
          </thead>
          <tbody className="bg-slate-700 divide-y divide-slate-600">
            {decisions.map((step, index) => (
              <tr key={index}>
                <td className="px-4 py-2 whitespace-normal text-sm text-slate-300">
                  ({step.nodeId}) {step.nodeText}
                </td>
                <td className={`px-4 py-2 whitespace-nowrap text-sm font-medium ${step.answer === 'Yes' ? 'text-green-400' : 'text-red-400'}`}>
                  {step.answer === 'Yes' ? t.path.yes : t.path.no}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};


const DiagnosticTreeNodeComponent: React.FC<DiagnosticTreeNodeProps> = ({
  node,
  history,
  onNavigate,
  onBack,
  onRestart,
  onExport,
  canGoBack,
  t,
}) => {
  const { bgColor, borderColor, textColor, titleColor, icon, contextBgColor } = getNodeStyling(node.type);
  const [isDetailsVisible, setIsDetailsVisible] = useState(false);

  useEffect(() => {
    setIsDetailsVisible(false); // Collapse details when navigating to a new node
  }, [node.id]);


  const isEndNode = !node.yesNodeId && !node.noNodeId && !node.nextNodeId && 
                    (node.type === NodeType.OUTCOME || node.type === NodeType.ALERT || node.type === NodeType.INTERVENTION);

  const nodeTypeText = t.nodeTypes[node.type.toLowerCase()] || (node.type.charAt(0) + node.type.slice(1).toLowerCase());

  return (
    <div className={`p-6 rounded-lg border-2 shadow-xl transition-all duration-300 ease-in-out transform hover:scale-[1.01] ${bgColor} ${borderColor}`}>
      <h2 className={`text-xl font-semibold mb-3 ${titleColor} flex items-center`}>
        <span className="text-2xl mr-2">{icon}</span>
        {nodeTypeText} (ID: {node.id})
      </h2>
      <p className={`text-lg mb-4 ${textColor}`}>{node.text}</p>

      {node.details && (
        <div className="mb-4">
          <button
            onClick={() => setIsDetailsVisible(!isDetailsVisible)}
            className={`w-full text-left px-4 py-2 text-sm font-medium rounded-md flex justify-between items-center transition-colors ${textColor} ${contextBgColor} hover:bg-opacity-80`}
            aria-expanded={isDetailsVisible}
          >
            <span>{isDetailsVisible ? t.node.hideDetails : t.node.showDetails}</span>
            <svg
              className={`w-5 h-5 transition-transform duration-200 ${isDetailsVisible ? 'rotate-180' : ''}`}
              xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
            </svg>
          </button>
          {isDetailsVisible && (
            <div className={`mt-2 text-sm p-3 rounded-b-md bg-opacity-70 ${contextBgColor} ${textColor}`}>
              <p>{node.details}</p>
            </div>
          )}
        </div>
      )}

      {node.type === NodeType.OUTCOME && <PathSummaryTable history={history} t={t} />}

      <div className="mt-6 space-y-3 sm:space-y-0 sm:space-x-3 flex flex-col sm:flex-row justify-start">
        {node.type === NodeType.QUESTION || node.type === NodeType.REASSESSMENT ? (
          <>
            <button
              onClick={() => onNavigate(node.yesNodeId, 'Yes')}
              className="w-full sm:w-auto px-6 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors focus:ring-2 focus:ring-green-500 focus:ring-opacity-75 font-medium shadow-md"
              aria-label={`${t.node.ariaSelectYes}: ${node.text}`}
            >
              {t.node.yes}
            </button>
            <button
              onClick={() => onNavigate(node.noNodeId, 'No')}
              className="w-full sm:w-auto px-6 py-3 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors focus:ring-2 focus:ring-red-500 focus:ring-opacity-75 font-medium shadow-md"
              aria-label={`${t.node.ariaSelectNo}: ${node.text}`}
            >
              {t.node.no}
            </button>
          </>
        ) : (node.type === NodeType.INTERVENTION || node.type === NodeType.ALERT || node.type === NodeType.OUTCOME) && node.nextNodeId ? (
           <button
            onClick={() => onNavigate(node.nextNodeId)}
            className="w-full sm:w-auto px-6 py-3 bg-teal-600 text-white rounded-md hover:bg-teal-700 transition-colors focus:ring-2 focus:ring-teal-500 font-medium shadow-md"
            aria-label={`${t.node.ariaContinue}: ${node.text}`}
          >
            {t.node.continue}
          </button>
        ) : null}

        {isEndNode && (
            <p className={`italic ${textColor} p-2 rounded ${contextBgColor}`}>
              {t.node.endNodeMessage}
            </p>
        )}
      </div>
      <div className="mt-8 pt-4 border-t border-slate-600 flex flex-col sm:flex-row space-y-3 sm:space-y-0 sm:space-x-3 items-center">
        {canGoBack && (
          <button
            onClick={onBack}
            className="w-full sm:w-auto px-6 py-2 bg-slate-600 text-slate-200 rounded-md hover:bg-slate-500 transition-colors focus:ring-2 focus:ring-slate-400 font-medium"
            aria-label={t.node.ariaGoBack}
          >
            {t.node.back}
          </button>
        )}
        <button
          onClick={onRestart}
          className="w-full sm:w-auto px-6 py-2 bg-amber-600 text-white rounded-md hover:bg-amber-700 transition-colors focus:ring-2 focus:ring-amber-500 font-medium"
          aria-label={t.node.ariaRestart}
        >
          {t.node.restart}
        </button>
        <button
          onClick={onExport}
          className="w-full sm:w-auto px-6 py-2 border border-slate-500 text-slate-300 rounded-md hover:bg-slate-700 hover:text-white transition-all focus:ring-2 focus:ring-slate-400 font-medium flex items-center justify-center"
          aria-label={t.node.ariaExport}
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5 mr-2">
            <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 0 0-3.375-3.375h-1.5A1.125 1.125 0 0 1 13.5 7.125v-1.5a3.375 3.375 0 0 0-3.375-3.375H8.25m.75 12 3 3m0 0 3-3m-3 3v-6m-1.5-9H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 0 0-9-9Z" />
          </svg>
          {t.node.export}
        </button>
      </div>
    </div>
  );
};

