import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { TreeNode } from '../types';
import { GEMINI_MODEL_NAME } from '../constants';

// Guidelines: Always use new GoogleGenAI({ apiKey: process.env.API_KEY });
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY }); 

export const getAiExplanation = async (userQuery: string, contextNode: TreeNode, lang: 'en' | 'es'): Promise<string> => {
  const model = GEMINI_MODEL_NAME;
  const responseLanguage = lang === 'es' ? 'Spanish' : 'English';

  // Build the context string dynamically for clarity and robustness.
  const contextLines = [
    `- Node ID: ${contextNode.id}`,
    `- Node Type: ${contextNode.type}`,
    `- Node Text: "${contextNode.text}"`
  ];
  if (contextNode.details) {
    // Ensure details are included clearly for the AI.
    contextLines.push(`- Node Details: "${contextNode.details}"`);
  }

  const systemInstruction = `You are an expert AI assistant specializing in ecological management and governance of invasive species, particularly conifer invasions.
You have access to Google Search to find recent or specific information if needed.
The user is currently navigating a diagnostic tree designed to help them understand and address these issues.
The entire user interface and diagnostic tree content are in ${responseLanguage}.
Current context from the diagnostic tree:
${contextLines.join('\n')}

The user has asked the following question related to this context. Please provide a concise, helpful, and relevant explanation or elaboration.
Focus on clarifying the concepts, suggesting implications, or offering examples if appropriate. Avoid generic advice not tied to the current diagnostic step.
IMPORTANT: You MUST respond in ${responseLanguage}.
If you use web search, please base your answer on the information found and clearly indicate the sources used at the end of your response.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: userQuery,
        config: {
            systemInstruction: systemInstruction,
            tools: [{googleSearch: {}}],
        }
    });

    // Guidelines: Use response.text property directly (it's a getter, not a method)
    let aiText = response.text;

    if (aiText) {
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks && groundingChunks.length > 0) {
            const uniqueUris = new Set<string>();
            const sources: string[] = [];
            groundingChunks.forEach(chunk => {
                if (chunk.web && chunk.web.uri && !uniqueUris.has(chunk.web.uri)) {
                    uniqueUris.add(chunk.web.uri);
                    sources.push(`- ${chunk.web.title || 'Untitled'}: ${chunk.web.uri}`);
                }
            });

            const sourcesHeader = lang === 'es' ? "\n\nFuentes de la web:\n" : "\n\nSources from the web:\n";
            if (sources.length > 0) {
              aiText += sourcesHeader + sources.join('\n');
            }
        }
        return aiText;
    } else {
        return "Sorry, I couldn't generate a response for that. The response format was unexpected.";
    }

  } catch (error) {
    console.error("Gemini API error:", error);
    if (error instanceof Error) {
        if (error.message.includes("API key not valid")) {
             return "Error: The configured Gemini API key is not valid. Please check your API key.";
        }
         return `Error interacting with AI: ${error.message}. Please try again later.`;
    }
    return "An unknown error occurred while contacting the AI service.";
  }
};

