interface ChatPanelProps {
  messages: ChatMessage[];
  onSendMessage: (message: string) => void;
  onExportChat: () => void;
  isLoading: boolean;
  currentNodeText: string;
  onClose: () => void;
  t: any;
}

const ChatPanel: React.FC<ChatPanelProps> = ({ messages, onSendMessage, onExportChat, isLoading, currentNodeText, onClose, t }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const speechRecognition = useRef<SpeechRecognition | null>(null);
  const initialInputRef = useRef<string>('');
  const messagesEndRef = useRef<null | HTMLDivElement>(null);

  useEffect(() => {
    const SpeechRecognitionAPI = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionAPI) {
      console.warn("Speech Recognition API not supported in this browser.");
      return;
    }

    const recognition: SpeechRecognition = new SpeechRecognitionAPI();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = t.langCode;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      if (event.error === 'not-allowed') {
        alert(t.chat.micPermission);
      }
      setIsListening(false);
    };

    recognition.onresult = (event) => {
      const transcript = Array.from(event.results)
        .map(result => result[0].transcript)
        .join('');
      setInput(initialInputRef.current + transcript);
    };

    speechRecognition.current = recognition;

    return () => {
      if (speechRecognition.current) {
        speechRecognition.current.stop();
      }
    };
  }, [t.langCode, t.chat.micPermission]);

  const handleToggleListening = () => {
    if (!speechRecognition.current) return;

    if (isListening) {
      speechRecognition.current.stop();
    } else {
      initialInputRef.current = input ? input + ' ' : '';
      speechRecognition.current.start();
    }
  };


  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSendMessage(input.trim());
      setInput('');
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-800 rounded-xl shadow-2xl border border-teal-700 overflow-hidden lg:h-auto lg:max-h-[calc(100vh-3rem)]">
      <div className="p-4 border-b border-teal-700 flex justify-between items-center">
        <h3 className="text-lg font-semibold text-teal-300 flex items-center">
            <SparklesIcon className="w-6 h-6 mr-2 text-teal-400" />
            {t.chat.title}
        </h3>
        <div className="flex items-center space-x-2">
          {messages.length > 0 && (
            <button 
              onClick={onExportChat} 
              className="text-teal-400 hover:text-teal-300 transition-colors p-1"
              title={t.chat.export}
              aria-label={t.chat.ariaExport}
            >
              <DocumentArrowDownIcon className="w-6 h-6" />
            </button>
          )}
          <button onClick={onClose} className="lg:hidden text-teal-400 hover:text-teal-300 transition-colors">
            <XMarkIcon className="w-6 h-6" />
          </button>
        </div>
      </div>
      <p className="px-4 pt-2 pb-1 text-xs text-slate-400 italic">
        {t.chat.contextLabel} "{currentNodeText.substring(0, 50)}{currentNodeText.length > 50 ? '...' : ''}"
      </p>

      <div className="flex-grow overflow-y-auto p-4 space-y-4 bg-slate-700/50">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-3 rounded-xl shadow ${
                msg.sender === 'user'
                  ? 'bg-teal-600 text-white rounded-br-none'
                  : 'bg-slate-600 text-slate-200 rounded-bl-none'
              }`}
            >
              <div className="flex items-center mb-1">
                {msg.sender === 'user' ? (
                  <UserCircleIcon className="w-5 h-5 mr-2 text-teal-200" />
                ) : (
                  <SparklesIcon className="w-5 h-5 mr-2 text-teal-400" />
                )}
                <span className="text-xs font-semibold">
                  {msg.sender === 'user' ? t.chat.user : t.chat.ai}
                </span>
              </div>
              <p className="text-sm whitespace-pre-wrap">{msg.text}</p>
              <p className="text-xs mt-1 opacity-70 text-right">
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="max-w-[80%] p-3 rounded-lg bg-slate-600 text-slate-200 rounded-bl-none animate-pulse">
               <div className="flex items-center mb-1">
                 <SparklesIcon className="w-5 h-5 mr-2 text-teal-400" />
                 <span className="text-xs font-semibold">{t.chat.ai}</span>
               </div>
              {t.chat.typing}
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="p-4 border-t border-teal-700 bg-slate-800">
        <div className="flex items-center space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={isListening ? t.chat.listening : t.chat.placeholder}
            className="flex-grow p-3 border border-teal-600 rounded-lg focus:ring-2 focus:ring-teal-500 focus:border-teal-500 transition-shadow bg-slate-700 text-slate-200 placeholder-slate-500"
            disabled={isLoading || isListening}
          />
           {speechRecognition.current && (
            <button
              type="button"
              onClick={handleToggleListening}
              disabled={isLoading}
              className={`p-3 rounded-lg transition-colors focus:ring-2 focus:ring-teal-500 focus:ring-opacity-75 shadow disabled:bg-slate-500 disabled:text-slate-400 ${
                isListening
                  ? 'bg-red-600 text-white animate-pulse'
                  : 'bg-slate-600 text-slate-200 hover:bg-slate-500'
              }`}
              aria-label={isListening ? t.chat.stopRecording : t.chat.startRecording}
            >
              {isListening ? <StopIcon className="w-5 h-5" /> : <MicrophoneIcon className="w-5 h-5" />}
            </button>
          )}
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="p-3 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:bg-slate-500 disabled:text-slate-400 transition-colors focus:ring-2 focus:ring-teal-500 focus:ring-opacity-75 shadow"
          >
            <PaperAirplaneIcon className="w-5 h-5" />
          </button>
        </div>
      </form>
    </div>
  );
};

export default ChatPanel;

import React, { useState, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticTreeNodeProps {
  node: TreeNode;
  history: HistoryStep[];
  onNavigate: (nodeId: string | undefined, answerGiven?: 'Yes' | 'No') => void;
  onBack: () => void;
  onRestart: () => void;
  onExport: () => void;
  canGoBack: boolean;
  t: any; // Translation object
}

const getNodeStyling = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return {
        bgColor: 'bg-slate-800',
        borderColor: 'border-teal-500/50',
        textColor: 'text-slate-100',
        titleColor: 'text-teal-400',
        accentBg: 'bg-teal-500',
        icon: '❓',
        iconBg: 'bg-teal-500/10',
        contextBgColor: 'bg-slate-700/50'
      };
    case NodeType.ALERT:
      return {
        bgColor: 'bg-slate-800',
        borderColor: 'border-rose-500/50',
        textColor: 'text-rose-50',
        titleColor: 'text-rose-400',
        accentBg: 'bg-rose-500',
        icon: '❗',
        iconBg: 'bg-rose-500/10',
        contextBgColor: 'bg-rose-950/30'
      };
    case NodeType.INTERVENTION:
      return {
        bgColor: 'bg-slate-800',
        borderColor: 'border-blue-500/50',
        textColor: 'text-blue-50',
        titleColor: 'text-blue-400',
        accentBg: 'bg-blue-500',
        icon: '💡',
        iconBg: 'bg-blue-500/10',
        contextBgColor: 'bg-blue-950/30'
      };
    case NodeType.OUTCOME:
      return {
        bgColor: 'bg-slate-800',
        borderColor: 'border-emerald-500/50',
        textColor: 'text-emerald-50',
        titleColor: 'text-emerald-400',
        accentBg: 'bg-emerald-500',
        icon: '🏁',
        iconBg: 'bg-emerald-500/10',
        contextBgColor: 'bg-emerald-950/30'
      };
    default:
      return {
        bgColor: 'bg-slate-800',
        borderColor: 'border-slate-500/50',
        textColor: 'text-slate-100',
        titleColor: 'text-slate-400',
        accentBg: 'bg-slate-500',
        icon: 'ℹ️',
        iconBg: 'bg-slate-500/10',
        contextBgColor: 'bg-slate-700/50'
      };
  }
};

const PathSummaryTable: React.FC<{ history: HistoryStep[], t: any }> = ({ history, t }) => {
  const decisions = history.filter(
    (step) => (step.nodeType === NodeType.QUESTION || step.nodeType === NodeType.REASSESSMENT) && step.answer
  );

  if (decisions.length === 0) {
    return null;
  }

  return (
    <div className="mt-6 mb-4 p-4 border border-slate-700 rounded-lg bg-slate-800/50 shadow-inner">
      <h3 className="text-md font-semibold text-slate-300 mb-3">{t.path.summary}</h3>
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-slate-700">
          <thead className="bg-slate-900/50">
            <tr>
              <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-slate-400 uppercase tracking-wider">
                {t.path.questionHeader}
              </th>
              <th scope="col" className="px-4 py-2 text-left text-xs font-medium text-slate-400 uppercase tracking-wider">
                {t.path.answerHeader}
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800">
            {decisions.map((step, index) => (
              <tr key={index} className="hover:bg-slate-700/30 transition-colors">
                <td className="px-4 py-2 whitespace-normal text-sm text-slate-300">
                  ({step.nodeId}) {step.nodeText}
                </td>
                <td className={`px-4 py-2 whitespace-nowrap text-sm font-bold ${step.answer === 'Yes' ? 'text-teal-400' : 'text-rose-400'}`}>
                  {step.answer === 'Yes' ? t.path.yes : t.path.no}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};


const DiagnosticTreeNodeComponent: React.FC<DiagnosticTreeNodeProps> = ({
  node,
  history,
  onNavigate,
  onBack,
  onRestart,
  onExport,
  canGoBack,
  t,
}) => {
  const { bgColor, borderColor, textColor, titleColor, icon, iconBg, accentBg, contextBgColor } = getNodeStyling(node.type);
  const [isDetailsVisible, setIsDetailsVisible] = useState(false);

  useEffect(() => {
    setIsDetailsVisible(false); // Collapse details when navigating to a new node
  }, [node.id]);


  const isEndNode = !node.yesNodeId && !node.noNodeId && !node.nextNodeId && 
                    (node.type === NodeType.OUTCOME || node.type === NodeType.ALERT || node.type === NodeType.INTERVENTION);

  const nodeTypeText = t.nodeTypes[node.type.toLowerCase()] || (node.type.charAt(0) + node.type.slice(1).toLowerCase());

  return (
    <div className={`relative overflow-hidden p-6 rounded-xl border-2 shadow-2xl transition-all duration-300 ease-in-out transform hover:scale-[1.005] ${bgColor} ${borderColor}`}>
      {/* Accent strip at top */}
      <div className={`absolute top-0 left-0 w-full h-1.5 ${accentBg}`} />

      <div className="flex items-start justify-between mb-4">
        <h2 className={`text-2xl font-bold ${titleColor} flex items-center`}>
          <div className={`p-2 rounded-lg mr-3 flex items-center justify-center ${iconBg}`}>
            <span className="text-2xl">{icon}</span>
          </div>
          {nodeTypeText}
        </h2>
        <span className="text-[10px] font-mono text-slate-500 bg-slate-900/50 px-2 py-1 rounded-md">ID: {node.id}</span>
      </div>

      <p className={`text-xl leading-relaxed mb-6 font-medium ${textColor}`}>{node.text}</p>

      {node.details && (
        <div className="mb-6">
          <button
            onClick={() => setIsDetailsVisible(!isDetailsVisible)}
            className={`w-full text-left px-4 py-3 text-sm font-semibold rounded-lg flex justify-between items-center transition-all bg-slate-900/30 ${textColor} hover:bg-slate-900/50`}
            aria-expanded={isDetailsVisible}
          >
            <span>{isDetailsVisible ? t.node.hideDetails : t.node.showDetails}</span>
            <svg
              className={`w-5 h-5 transition-transform duration-300 ${isDetailsVisible ? 'rotate-180' : ''}`}
              xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
            </svg>
          </button>
          {isDetailsVisible && (
            <div className={`mt-2 text-sm leading-relaxed p-4 rounded-lg bg-opacity-40 border border-white/5 ${contextBgColor} ${textColor} animate-fade-in`}>
              <p>{node.details}</p>
            </div>
          )}
        </div>
      )}

      {node.type === NodeType.OUTCOME && <PathSummaryTable history={history} t={t} />}

      <div className="mt-8 space-y-3 sm:space-y-0 sm:space-x-4 flex flex-col sm:flex-row justify-start">
        {node.type === NodeType.QUESTION || node.type === NodeType.REASSESSMENT ? (
          <>
            <button
              onClick={() => onNavigate(node.yesNodeId, 'Yes')}
              className="group relative w-full sm:w-auto px-10 py-4 bg-teal-600 text-white rounded-xl hover:bg-teal-500 transition-all focus:ring-4 focus:ring-teal-500/20 font-bold shadow-lg overflow-hidden"
              aria-label={`${t.node.ariaSelectYes}: ${node.text}`}
            >
              <span className="relative z-10">{t.node.yes}</span>
              <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
            </button>
            <button
              onClick={() => onNavigate(node.noNodeId, 'No')}
              className="group relative w-full sm:w-auto px-10 py-4 bg-rose-600 text-white rounded-xl hover:bg-rose-500 transition-all focus:ring-4 focus:ring-rose-500/20 font-bold shadow-lg overflow-hidden"
              aria-label={`${t.node.ariaSelectNo}: ${node.text}`}
            >
              <span className="relative z-10">{t.node.no}</span>
              <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
            </button>
          </>
        ) : (node.type === NodeType.INTERVENTION || node.type === NodeType.ALERT || node.type === NodeType.OUTCOME) && node.nextNodeId ? (
           <button
            onClick={() => onNavigate(node.nextNodeId)}
            className="group relative w-full sm:w-auto px-10 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-all focus:ring-4 focus:ring-blue-500/20 font-bold shadow-lg overflow-hidden"
            aria-label={`${t.node.ariaContinue}: ${node.text}`}
          >
            <span className="relative z-10">{t.node.continue}</span>
            <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
          </button>
        ) : null}

        {isEndNode && (
            <div className={`italic ${textColor} p-4 rounded-xl bg-opacity-30 border border-white/5 font-medium ${contextBgColor}`}>
              {t.node.endNodeMessage}
            </div>
        )}
      </div>

      <div className="mt-12 pt-6 border-t border-slate-700/50 flex flex-col sm:flex-row space-y-3 sm:space-y-0 sm:space-x-3 items-center">
        {canGoBack && (
          <button
            onClick={onBack}
            className="w-full sm:w-auto px-6 py-2.5 bg-slate-700 text-slate-200 rounded-lg hover:bg-slate-600 transition-all focus:ring-2 focus:ring-slate-500 font-semibold border border-slate-600/50"
            aria-label={t.node.ariaGoBack}
          >
            {t.node.back}
          </button>
        )}
        <button
          onClick={onRestart}
          className="w-full sm:w-auto px-6 py-2.5 bg-amber-600/90 text-white rounded-lg hover:bg-amber-600 transition-all focus:ring-2 focus:ring-amber-500 font-semibold shadow-md"
          aria-label={t.node.ariaRestart}
        >
          {t.node.restart}
        </button>
        <div className="flex-grow" />
        <button
          onClick={onExport}
          className="w-full sm:w-auto px-6 py-2.5 border border-slate-600 text-slate-400 rounded-lg hover:bg-slate-700 hover:text-white transition-all focus:ring-2 focus:ring-slate-500 font-semibold flex items-center justify-center group"
          aria-label={t.node.ariaExport}
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 mr-2 group-hover:scale-110 transition-transform">
            <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 0 0-3.375-3.375h-1.5A1.125 1.125 0 0 1 13.5 7.125v-1.5a3.375 3.375 0 0 0-3.375-3.375H8.25m.75 12 3 3m0 0 3-3m-3 3v-6m-1.5-9H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 0 0-9-9Z" />
          </svg>
          {t.node.export}
        </button>
      </div>
    </div>
  );
};

