interface ChatPanelProps {
  messages: ChatMessage[];
  onSendMessage: (message: string) => void;
  onExportChat: () => void;
  isLoading: boolean;
  currentNodeText: string;
  onClose: () => void;
  t: any;
  expanded?: boolean;
}

const ChatPanel: React.FC<ChatPanelProps> = ({ messages, onSendMessage, onExportChat, isLoading, currentNodeText, onClose, t, expanded = false }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const speechRecognition = useRef<SpeechRecognition | null>(null);
  const initialInputRef = useRef<string>('');
  const messagesEndRef = useRef<null | HTMLDivElement>(null);

  useEffect(() => {
    const SpeechRecognitionAPI = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionAPI) {
      console.warn("Speech Recognition API not supported in this browser.");
      return;
    }

    const recognition: SpeechRecognition = new SpeechRecognitionAPI();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = t.langCode;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      if (event.error === 'not-allowed') {
        alert(t.chat.micPermission);
      }
      setIsListening(false);
    };

    recognition.onresult = (event) => {
      const transcript = Array.from(event.results)
        .map(result => result[0].transcript)
        .join('');
      setInput(initialInputRef.current + transcript);
    };

    speechRecognition.current = recognition;

    return () => {
      if (speechRecognition.current) {
        speechRecognition.current.stop();
      }
    };
  }, [t.langCode, t.chat.micPermission]);

  const handleToggleListening = () => {
    if (!speechRecognition.current) return;

    if (isListening) {
      speechRecognition.current.stop();
    } else {
      initialInputRef.current = input ? input + ' ' : '';
      speechRecognition.current.start();
    }
  };


  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSendMessage(input.trim());
      setInput('');
    }
  };

  return (
    <div className={`flex flex-col bg-slate-800 rounded-xl shadow-2xl border border-teal-700 overflow-hidden transition-all duration-300 ${expanded ? 'w-full' : 'h-full'}`}>
      <div className="p-4 border-b border-teal-700 flex justify-between items-center bg-slate-800/80 backdrop-blur-sm sticky top-0 z-10">
        <h3 className="text-xl font-bold text-teal-300 flex items-center">
            <SparklesIcon className="w-6 h-6 mr-3 text-teal-400" />
            {t.chat.title}
        </h3>
        <div className="flex items-center space-x-4">
          {messages.length > 0 && (
            <button 
              onClick={onExportChat} 
              className="text-teal-400 hover:text-teal-300 transition-all p-2 rounded-lg hover:bg-teal-500/10 flex items-center space-x-2"
              title={t.chat.export}
              aria-label={t.chat.ariaExport}
            >
              <DocumentArrowDownIcon className="w-6 h-6" />
              <span className="hidden sm:inline text-sm font-semibold">{t.chat.export}</span>
            </button>
          )}
          {!expanded && (
            <button onClick={onClose} className="lg:hidden text-teal-400 hover:text-teal-300 transition-colors">
              <XMarkIcon className="w-6 h-6" />
            </button>
          )}
        </div>
      </div>

      <div className="px-6 py-3 border-b border-teal-800/30 bg-slate-900/40">
        <p className="text-sm text-slate-400 italic">
          <span className="font-bold text-teal-500/80 uppercase tracking-wider text-[10px] mr-2 not-italic">{t.chat.contextLabel}</span> 
          "{currentNodeText.substring(0, 100)}{currentNodeText.length > 100 ? '...' : ''}"
        </p>
      </div>

      <div className={`flex-grow overflow-y-auto p-6 space-y-6 bg-slate-900/20 scrollbar-thin scrollbar-thumb-teal-900 ${expanded ? 'min-h-[400px] max-h-[600px] lg:min-h-[500px]' : 'max-h-[calc(100vh-3rem)]'}`}>
        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4 py-20">
            <SparklesIcon className="w-16 h-16 opacity-10" />
            <p className="text-lg font-medium opacity-40">{t.chat.placeholder}</p>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] lg:max-w-[75%] p-4 rounded-2xl shadow-lg transition-all ${
                msg.sender === 'user'
                  ? 'bg-teal-600 text-white rounded-br-none'
                  : 'bg-slate-700 text-slate-200 rounded-bl-none border border-teal-900/30'
              }`}
            >
              <div className="flex items-center mb-2">
                {msg.sender === 'user' ? (
                  <UserCircleIcon className="w-5 h-5 mr-2 text-teal-200" />
                ) : (
                  <SparklesIcon className="w-5 h-5 mr-2 text-teal-400" />
                )}
                <span className="text-xs font-bold uppercase tracking-widest opacity-80">
                  {msg.sender === 'user' ? t.chat.user : t.chat.ai}
                </span>
              </div>
              <p className="text-base leading-relaxed whitespace-pre-wrap">{msg.text}</p>
              <div className="flex justify-end mt-2">
                <span className="text-[10px] font-mono opacity-50">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="max-w-[80%] p-4 rounded-2xl bg-slate-700 text-slate-200 rounded-bl-none border border-teal-900/30 animate-pulse">
               <div className="flex items-center mb-2">
                 <SparklesIcon className="w-5 h-5 mr-2 text-teal-400" />
                 <span className="text-xs font-bold uppercase tracking-widest opacity-80">{t.chat.ai}</span>
               </div>
              <div className="flex space-x-1 items-center">
                 <div className="w-2 h-2 bg-teal-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                 <div className="w-2 h-2 bg-teal-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                 <div className="w-2 h-2 bg-teal-500 rounded-full animate-bounce"></div>
                 <span className="ml-2 text-sm italic opacity-60">{t.chat.typing}</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="p-6 border-t border-teal-700/50 bg-slate-800/50">
        <div className="flex items-center space-x-4 max-w-4xl mx-auto">
          <div className="relative flex-grow">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={isListening ? t.chat.listening : t.chat.placeholder}
              className="w-full p-4 pr-12 border border-teal-700 rounded-xl focus:ring-4 focus:ring-teal-500/20 focus:border-teal-500 transition-all bg-slate-900 text-slate-100 placeholder-slate-500 shadow-inner"
              disabled={isLoading || isListening}
            />
          </div>

           {speechRecognition.current && (
            <button
              type="button"
              onClick={handleToggleListening}
              disabled={isLoading}
              className={`p-4 rounded-xl transition-all focus:ring-4 focus:ring-teal-500/20 shadow-lg disabled:bg-slate-700 disabled:text-slate-500 ${
                isListening
                  ? 'bg-rose-600 text-white animate-pulse'
                  : 'bg-slate-700 text-teal-400 hover:bg-slate-600 hover:text-teal-300'
              }`}
              title={isListening ? t.chat.stopRecording : t.chat.startRecording}
              aria-label={isListening ? t.chat.stopRecording : t.chat.startRecording}
            >
              {isListening ? <StopIcon className="w-6 h-6" /> : <MicrophoneIcon className="w-6 h-6" />}
            </button>
          )}

          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="p-4 bg-teal-600 text-white rounded-xl hover:bg-teal-500 disabled:bg-slate-700 disabled:text-slate-500 transition-all focus:ring-4 focus:ring-teal-500/20 shadow-lg flex items-center justify-center min-w-[60px]"
          >
            <PaperAirplaneIcon className="w-6 h-6" />
          </button>
        </div>
        <p className="text-[10px] text-center text-slate-500 mt-4 uppercase tracking-[0.2em]">{t.footer}</p>
      </form>
    </div>
  );
};

export default ChatPanel;

export enum NodeType {
  QUESTION = 'QUESTION',
  ALERT = 'ALERT',
  INTERVENTION = 'INTERVENTION',
  OUTCOME = 'OUTCOME',
  REASSESSMENT = 'REASSESSMENT',
}

export interface TreeNode {
  id: string;
  type: NodeType;
  text: string;
  details?: string;
  yesNodeId?: string;
  noNodeId?: string;
  nextNodeId?: string;
  // Positioning for the graph visualization
  position?: { x: number; y: number };
}

export interface ChatMessage {
  id: string;
  sender: 'user' | 'ai';
  text: string;
  timestamp: Date;
}

export interface HistoryStep {
  nodeId: string;
  nodeText: string;
  nodeType: NodeType;
  answer?: 'Yes' | 'No';
}

import React from 'react';
import { TreeNode, NodeType } from '../types';

interface DiagnosticGraphProps {
  nodes: Record<string, TreeNode>;
  history: string[];
  activeNodeId: string;
  onNodeClick: (id: string) => void;
  t: any;
}

const getNodeColor = (type: NodeType, isActive: boolean, isVisited: boolean) => {
  if (isActive) return 'stroke-teal-400 fill-slate-700 shadow-[0_0_15px_rgba(45,212,191,0.5)]';
  if (isVisited) return 'stroke-slate-500 fill-slate-800 opacity-80';

  switch (type) {
    case NodeType.QUESTION: return 'stroke-teal-600/40 fill-slate-900/40';
    case NodeType.ALERT: return 'stroke-rose-600/40 fill-slate-900/40';
    case NodeType.INTERVENTION: return 'stroke-blue-600/40 fill-slate-900/40';
    case NodeType.OUTCOME: return 'stroke-emerald-600/40 fill-slate-900/40';
    default: return 'stroke-slate-600/40 fill-slate-900/40';
  }
};

const DiagnosticGraph: React.FC<DiagnosticGraphProps> = ({ nodes, history, activeNodeId, onNodeClick, t }) => {
  const nodeIds = Object.keys(nodes);
  const visitedSet = new Set(history);

  // Layout calculation (Simple vertical tree layout if positions aren't defined)
  // In a real app, we'd use a layout library or pre-defined coordinates in i18n
  // For this demo, we'll assume the positions are defined or we use a fallback grid

  const renderConnection = (fromId: string, toId: string | undefined, colorClass: string) => {
    if (!toId || !nodes[toId]) return null;
    const from = nodes[fromId].position || { x: 0, y: 0 };
    const to = nodes[toId].position || { x: 0, y: 0 };

    const isPath = visitedSet.has(fromId) && (visitedSet.has(toId) || activeNodeId === toId);

    return (
      <line
        key={`${fromId}-${toId}`}
        x1={from.x} y1={from.y}
        x2={to.x} y2={to.y}
        className={`transition-all duration-700 ${isPath ? 'stroke-teal-500 stroke-[3px]' : 'stroke-slate-700/30 stroke-[1.5px]'}`}
      />
    );
  };

  return (
    <div className="w-full bg-slate-900/50 rounded-2xl border border-slate-700/50 p-4 mb-8 overflow-hidden relative group">
      <div className="absolute top-4 left-4 z-10">
        <h3 className="text-xs font-bold uppercase tracking-widest text-slate-500">{t.legend.graphView}</h3>
      </div>

      <svg viewBox="0 0 1000 600" className="w-full h-auto cursor-grab active:cursor-grabbing">
        <defs>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {/* Render Connections */}
        {nodeIds.map(id => {
          const node = nodes[id];
          return (
            <React.Fragment key={`conn-${id}`}>
              {renderConnection(id, node.yesNodeId, 'stroke-teal-500')}
              {renderConnection(id, node.noNodeId, 'stroke-rose-500')}
              {renderConnection(id, node.nextNodeId, 'stroke-blue-500')}
            </React.Fragment>
          );
        })}

        {/* Render Nodes */}
        {nodeIds.map(id => {
          const node = nodes[id];
          const pos = node.position || { x: 0, y: 0 };
          const isActive = activeNodeId === id;
          const isVisited = visitedSet.has(id);
          const colorClasses = getNodeColor(node.type, isActive, isVisited);

          return (
            <g 
              key={`node-${id}`} 
              className="cursor-pointer transition-all duration-300"
              onClick={() => onNodeClick(id)}
            >
              <circle
                cx={pos.x} cy={pos.y}
                r={isActive ? 22 : 16}
                className={`${colorClasses} border-2 transition-all duration-300 ${isActive ? 'filter-glow' : ''}`}
                style={isActive ? { filter: 'url(#glow)' } : {}}
              />
              {isActive && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={30}
                  className="stroke-teal-500/20 fill-none animate-ping"
                />
              )}
              <text
                x={pos.x} y={pos.y + 35}
                textAnchor="middle"
                className={`text-[10px] font-mono fill-slate-400 font-bold ${isActive ? 'fill-teal-300' : ''}`}
              >
                {id}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
};

export default DiagnosticGraph;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { TreeNode, ChatMessage, NodeType, HistoryStep } from './types';
import DiagnosticTreeNodeComponent from './components/DiagnosticTreeNodeComponent';
import ChatPanel from './components/ChatPanel';
import LegendComponent from './components/LegendComponent';
import LanguageSelector from './components/LanguageSelector';
import TutorialModal from './components/TutorialModal';
import DiagnosticGraph from './components/DiagnosticGraph';
import { getAiExplanation, getAiSummaryFeedback } from './services/geminiService';
import { translationsEN, DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID_EN } from './i18n/en';
import { translationsES, DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID_ES } from './i18n/es';

const TreeIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 2.25H2.25A2.25 2.25 0 0 0 0 4.5v15A2.25 2.25 0 0 0 2.25 21.75h15a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75V6.75A2.25 2.25 0 0 0 16.5 4.5h-6.75a2.25 2.25 0 0 0-2.25 2.25v6.75a2.25 2.25 0 0 0 2.25 2.25h6.75a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75h-1.5m1.5 0v-1.5m0 1.5L12 9m3 3L12 9m0 0L9 12m3-3v1.5m0 0H9m3.75-3.75L12 6.75m0 0L10.125 5.25M12 6.75V5.25m0 1.5L13.875 5.25m-3.75 0h.008v.008h-.008V5.25Z" />
  </svg>
);

const ChatBubbleIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 12a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0H8.25m4.125 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0H12m4.125 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm0 0h-.375M21 12c0 4.556-3.86 8.25-8.625 8.25S3.75 16.556 3.75 12 7.61 3.75 12.375 3.75 21 7.444 21 12Z" />
  </svg>
);

type Language = 'en' | 'es';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language | null>(null);
  const [showTutorial, setShowTutorial] = useState(false);
  const [appReady, setAppReady] = useState(false);

  const [currentNodeId, setCurrentNodeId] = useState<string>('');
  const [history, setHistory] = useState<HistoryStep[]>([]);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState<boolean>(false);

  const chatRef = useRef<HTMLDivElement>(null);

  const { t, DIAGNOSTIC_TREE_DATA, INITIAL_NODE_ID } = lang === 'es' 
    ? { t: translationsES, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID: INITIAL_NODE_ID_ES }
    : { t: translationsEN, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID: INITIAL_NODE_ID_EN };

  useEffect(() => {
    if (lang) {
      setCurrentNodeId(INITIAL_NODE_ID);
      const hasSeenTutorial = localStorage.getItem('hasSeenTutorial');
      if (!hasSeenTutorial) {
        setShowTutorial(true);
      } else {
        setAppReady(true);
      }
    }
  }, [lang, INITIAL_NODE_ID]);

  const handleSelectLanguage = (selectedLang: Language) => {
    setLang(selectedLang);
  };

  const handleCloseTutorial = () => {
    setShowTutorial(false);
    localStorage.setItem('hasSeenTutorial', 'true');
    setAppReady(true);
  };

  const currentNode = DIAGNOSTIC_TREE_DATA[currentNodeId];

  const navigateToNode = useCallback((nodeId: string | undefined, answerGiven?: 'Yes' | 'No') => {
    if (nodeId && DIAGNOSTIC_TREE_DATA[nodeId]) {
      const currentFullNode = DIAGNOSTIC_TREE_DATA[currentNodeId];
      if (!currentFullNode) return; 

      const newHistoryStep: HistoryStep = {
        nodeId: currentNodeId,
        nodeText: currentFullNode.text,
        nodeType: currentFullNode.type,
      };
      if (currentFullNode.type === NodeType.QUESTION || currentFullNode.type === NodeType.REASSESSMENT) {
        newHistoryStep.answer = answerGiven;
      }

      setHistory(prev => [...prev, newHistoryStep]);
      setCurrentNodeId(nodeId);
    }
  }, [currentNodeId, DIAGNOSTIC_TREE_DATA]);

  const handleBack = useCallback(() => {
    if (history.length > 0) {
      const lastStep = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setCurrentNodeId(lastStep.nodeId);
    }
  }, [history]);

  const handleRestart = useCallback(() => {
    setHistory([]);
    setCurrentNodeId(INITIAL_NODE_ID);
    setChatMessages([]); 
  }, [INITIAL_NODE_ID]);

  const handleViewSummary = useCallback(async () => {
    if (history.length === 0) return;

    setIsChatLoading(true);
    scrollToChat();

    try {
      const summaryFeedback = await getAiSummaryFeedback(history, lang || 'en');
      const aiMessage: ChatMessage = {
        id: Date.now().toString() + 'summary',
        sender: 'ai',
        text: summaryFeedback,
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      console.error("Summary error:", error);
    } finally {
      setIsChatLoading(false);
    }
  }, [history, lang]);

  const handleExport = useCallback(() => {
    const reportDate = new Date().toLocaleString();
    let content = `${t.appTitle}\n${"=".repeat(t.appTitle.length)}\n\n`;
    content += `${lang === 'es' ? 'Fecha' : 'Date'}: ${reportDate}\n`;
    content += `${lang === 'es' ? 'Idioma' : 'Language'}: ${lang === 'es' ? 'Español' : 'English'}\n\n`;

    content += `${t.path.summary}\n${"-".repeat(t.path.summary.length)}\n\n`;

    history.forEach((step, index) => {
      const nodeData = DIAGNOSTIC_TREE_DATA[step.nodeId];
      content += `[${index + 1}] (${step.nodeId}) ${step.nodeText}\n`;
      if (step.answer) {
        content += `    ${t.path.answerHeader}: ${step.answer === 'Yes' ? t.path.yes : t.path.no}\n`;
      }
      if (nodeData?.details) {
        content += `    Context: ${nodeData.details}\n`;
      }
      content += `\n`;
    });

    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${t.node.exportFilename || 'Diagnostic_Report'}_${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, [history, DIAGNOSTIC_TREE_DATA, t, lang]);

  const handleUserMessage = useCallback(async (userQuery: string) => {
    if (!userQuery.trim() || !lang) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString() + 'user',
      sender: 'user',
      text: userQuery,
      timestamp: new Date(),
    };
    setChatMessages(prev => [...prev, userMessage]);
    setIsChatLoading(true);

    try {
      const aiResponseText = await getAiExplanation(userQuery, currentNode, lang);
      const aiMessage: ChatMessage = {
        id: Date.now().toString() + 'ai',
        sender: 'ai',
        text: aiResponseText,
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, aiMessage]);
    } catch (error) {
      const errorMessage: ChatMessage = {
        id: Date.now().toString() + 'error',
        sender: 'ai',
        text: t.chat.error,
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsChatLoading(false);
    }
  }, [currentNode, lang, t]);

  const scrollToChat = () => {
    chatRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  if (!lang) {
    return <LanguageSelector onSelectLanguage={handleSelectLanguage} />;
  }

  if (!appReady) {
    return (
      <>
        <TutorialModal isOpen={showTutorial} onClose={handleCloseTutorial} t={t} />
        <div className="min-h-screen bg-gradient-to-br from-black via-slate-900 to-teal-900" />
      </>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-slate-900 to-teal-900 flex flex-col items-center p-4 selection:bg-teal-500 selection:text-white">
      <TutorialModal isOpen={showTutorial} onClose={handleCloseTutorial} t={t} />
      <header className="w-full max-w-5xl mb-6 text-center">
        <div className="flex items-center justify-center space-x-3 mb-2">
           <TreeIcon className="w-12 h-12 text-teal-400" />
          <h1 className="text-4xl font-bold text-stone-100">{t.appTitle}</h1>
        </div>
        <p className="text-lg text-teal-300">{t.appSubtitle}</p>
      </header>

      <div className="w-full max-w-5xl flex flex-col gap-8">
        {/* Interactive Graph Visualization */}
        <DiagnosticGraph 
          nodes={DIAGNOSTIC_TREE_DATA}
          history={history.map(h => h.nodeId)}
          activeNodeId={currentNodeId}
          onNodeClick={(id) => setCurrentNodeId(id)}
          t={t}
        />

        {/* Main Diagnostic Panel */}
        <main className="w-full bg-slate-800 p-6 rounded-xl shadow-2xl border border-teal-700">
          <DiagnosticTreeNodeComponent
            node={currentNode}
            history={history}
            onNavigate={navigateToNode}
            onBack={handleBack}
            onRestart={handleRestart}
            onExport={handleExport}
            canGoBack={history.length > 0}
            t={t}
          />

          <div className="mt-6 flex justify-center">
            <button
              onClick={handleViewSummary}
              className="px-8 py-3 bg-teal-600 hover:bg-teal-500 text-white rounded-xl font-bold shadow-xl transition-all transform hover:scale-105 active:scale-95 disabled:opacity-50"
              disabled={history.length === 0}
            >
              {t.path.viewSummaryButton}
            </button>
          </div>

          <LegendComponent t={t} />
        </main>

        {/* Expanded AI Assistant Panel */}
        <section ref={chatRef} className="w-full">
          <ChatPanel
            messages={chatMessages}
            onSendMessage={handleUserMessage}
            onExportChat={() => {}} 
            isLoading={isChatLoading}
            currentNodeText={currentNode.text}
            onClose={() => {}}
            t={t}
            expanded={true}
          />
        </section>
      </div>

      <footer className="mt-12 mb-8 text-center text-sm text-teal-400">
        <p>&copy; {new Date().getFullYear()} {t.footer}</p>
