  REASSESSMENT = 'REASSESSMENT',
}

export interface TreeNode {
  id: string;
  type: NodeType;
  text: string;
  details?: string;
  yesNodeId?: string;
  noNodeId?: string;
  nextNodeId?: string;
  position?: { x: number; y: number };
}

export interface ChatMessage {
