import React, { useState, useRef, useMemo } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticGraphProps {
  nodes: Record<string, TreeNode>;
  history: HistoryStep[];
  activeNodeId: string;
  onNodeClick: (id: string) => void;
  t: any;
}

const getRankingColor = (value: number | undefined) => {
  if (value === undefined) return 'stroke-slate-700 fill-slate-900/40';

  // Color mapping: 0 (Red) -> 50 (Slate) -> 100 (Teal/Green)
  if (value < 45) {
    const intensity = Math.round((45 - value) * 5.6); // 0-255ish
    return `stroke-rose-500 fill-rose-950/40`;
  } else if (value > 55) {
    return `stroke-teal-500 fill-teal-950/40`;
  }
  return 'stroke-slate-400 fill-slate-800';
};

const DiagnosticGraph: React.FC<DiagnosticGraphProps> = ({ nodes, history, activeNodeId, onNodeClick, t }) => {
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef({ x: 0, y: 0 });

  const nodeIds = Object.keys(nodes);
  const historyMap = useMemo(() => {
    const map = new Map<string, number>();
    history.forEach(h => map.set(h.nodeId, h.answerValue ?? 50));
    return map;
  }, [history]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    dragStart.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setOffset({
      x: e.clientX - dragStart.current.x,
      y: e.clientY - dragStart.current.y
    });
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleWheel = (e: React.WheelEvent) => {
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setZoom(prev => Math.min(Math.max(prev * delta, 0.2), 3));
  };

  const renderConnection = (fromId: string, toId: string | undefined) => {
    if (!toId || !nodes[toId]) return null;
    const from = nodes[fromId].position || { x: 0, y: 0 };
    const to = nodes[toId].position || { x: 0, y: 0 };

    const isVisited = historyMap.has(fromId) && (historyMap.has(toId) || activeNodeId === toId);
    const value = historyMap.get(fromId);

    // Line color based on answer
    let color = 'stroke-slate-800/30';
    if (isVisited) {
      if (value !== undefined) {
        color = value >= 50 ? 'stroke-teal-500/60' : 'stroke-rose-500/60';
      } else {
        color = 'stroke-blue-500/60';
      }
    }

    return (
      <line
        key={`${fromId}-${toId}`}
        x1={from.x} y1={from.y}
        x2={to.x} y2={to.y}
        className={`transition-all duration-500 ${color}`}
        strokeWidth={isVisited ? 3 : 1.5}
      />
    );
  };

  return (
    <div className="w-full bg-slate-900/80 rounded-2xl border border-teal-900/30 p-0 mb-8 overflow-hidden relative group h-[400px]">
      <div className="absolute top-4 left-4 z-20 flex flex-col space-y-2">
        <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-500 bg-slate-900/80 px-2 py-1 rounded">
          {t.legend.graphView}
        </h3>
        <div className="flex space-x-1">
           <button onClick={() => setZoom(z => z * 1.2)} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700">+</button>
           <button onClick={() => setZoom(z => z * 0.8)} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700">-button</button>
           <button onClick={() => {setZoom(1); setOffset({x:0, y:0});}} className="bg-slate-800 hover:bg-slate-700 text-white px-2 h-8 rounded border border-slate-700 text-xs">Reset</button>
        </div>
      </div>

      <div 
        className="w-full h-full cursor-grab active:cursor-grabbing"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      >
        <svg width="100%" height="100%" viewBox="0 0 1000 600" preserveAspectRatio="xMidYMid slice">
          <g transform={`translate(${offset.x}, ${offset.y}) scale(${zoom})`}>
            {/* Connections */}
            {nodeIds.map(id => {
              const node = nodes[id];
              return (
                <React.Fragment key={`conn-${id}`}>
                  {renderConnection(id, node.yesNodeId)}
                  {renderConnection(id, node.noNodeId)}
                  {renderConnection(id, node.nextNodeId)}
                </React.Fragment>
              );
            })}

            {/* Nodes */}
            {nodeIds.map(id => {
              const node = nodes[id];
              const pos = node.position || { x: 0, y: 0 };
              const isActive = activeNodeId === id;
              const isVisited = historyMap.has(id);
              const value = historyMap.get(id);

              const colorClasses = getRankingColor(value);
              const size = isActive ? 24 : 16;
              const borderRadius = value !== undefined ? (value > 50 ? 4 : 12) : 100; // Morph shape slightly based on value

              return (
                <g 
                  key={`node-${id}`} 
                  className="cursor-pointer transition-all duration-300"
                  onClick={() => onNodeClick(id)}
                >
                  <rect
                    x={pos.x - size/2} y={pos.y - size/2}
                    width={size} height={size}
                    rx={borderRadius}
                    className={`${isActive ? 'stroke-teal-400 fill-slate-700' : colorClasses} stroke-2 transition-all duration-300`}
                  />
                  {isActive && (
                    <circle
                      cx={pos.x} cy={pos.y}
                      r={30}
                      className="stroke-teal-500/20 fill-none animate-ping"
                    />
                  )}
                  <text
                    x={pos.x} y={pos.y + 35}
                    textAnchor="middle"
                    className={`text-[9px] font-mono fill-slate-500 font-bold pointer-events-none ${isActive ? 'fill-teal-300' : ''}`}
                  >
                    {id}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>
      </div>
    </div>
  );
};

export default DiagnosticGraph;

import React, { useState, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticTreeNodeProps {
  node: TreeNode;
  history: HistoryStep[];
  onNavigateValue: (nodeId: string | undefined, value: number) => void;
  onNavigateDirect: (nodeId: string | undefined) => void;
  onBack: () => void;
  onRestart: () => void;
  onExport: () => void;
  canGoBack: boolean;
  t: any;
}

const getNodeStyling = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return { bgColor: 'bg-slate-800', borderColor: 'border-teal-500/50', textColor: 'text-slate-100', titleColor: 'text-teal-400', accentBg: 'bg-teal-500', icon: '❓', iconBg: 'bg-teal-500/10' };
    case NodeType.ALERT:
      return { bgColor: 'bg-slate-800', borderColor: 'border-rose-500/50', textColor: 'text-rose-50', titleColor: 'text-rose-400', accentBg: 'bg-rose-500', icon: '❗', iconBg: 'bg-rose-500/10' };
    case NodeType.INTERVENTION:
      return { bgColor: 'bg-slate-800', borderColor: 'border-blue-500/50', textColor: 'text-blue-50', titleColor: 'text-blue-400', accentBg: 'bg-blue-500', icon: '💡', iconBg: 'bg-blue-500/10' };
    case NodeType.OUTCOME:
      return { bgColor: 'bg-slate-800', borderColor: 'border-emerald-500/50', textColor: 'text-emerald-50', titleColor: 'text-emerald-400', accentBg: 'bg-emerald-500', icon: '🏁', iconBg: 'bg-emerald-500/10' };
    default:
      return { bgColor: 'bg-slate-800', borderColor: 'border-slate-500/50', textColor: 'text-slate-100', titleColor: 'text-slate-400', accentBg: 'bg-slate-500', icon: 'ℹ️', iconBg: 'bg-slate-500/10' };
  }
};

const DiagnosticTreeNodeComponent: React.FC<DiagnosticTreeNodeProps> = ({
  node,
  history,
  onNavigateValue,
  onNavigateDirect,
  onBack,
  onRestart,
  onExport,
  canGoBack,
  t,
}) => {
  const { bgColor, borderColor, textColor, titleColor, icon, iconBg, accentBg } = getNodeStyling(node.type);
  const [isDetailsVisible, setIsDetailsVisible] = useState(false);
  const [sliderValue, setSliderValue] = useState(50);

  useEffect(() => {
    setIsDetailsVisible(false);
    setSliderValue(50);
  }, [node.id]);

  const isQuestion = node.type === NodeType.QUESTION || node.type === NodeType.REASSESSMENT;
  const isEndNode = !node.yesNodeId && !node.noNodeId && !node.nextNodeId;

  const getSliderLabel = (val: number) => {
    if (val < 20) return t.ranking.noStrong;
    if (val < 45) return t.ranking.noWeak;
    if (val < 55) return t.ranking.neutral;
    if (val < 80) return t.ranking.yesWeak;
    return t.ranking.yesStrong;
  };

  const handleNextWithSlider = () => {
    const targetId = sliderValue >= 50 ? node.yesNodeId : node.noNodeId;
    onNavigateValue(targetId, sliderValue);
  };

  return (
    <div className={`relative overflow-hidden p-6 rounded-xl border-2 shadow-2xl transition-all ${bgColor} ${borderColor}`}>
      <div className={`absolute top-0 left-0 w-full h-1.5 ${accentBg}`} />

      <div className="flex items-start justify-between mb-4">
        <h2 className={`text-2xl font-bold ${titleColor} flex items-center`}>
          <div className={`p-2 rounded-lg mr-3 flex items-center justify-center ${iconBg}`}>
            <span className="text-2xl">{icon}</span>
          </div>
          {t.nodeTypes[node.type.toLowerCase()]}
        </h2>
        <span className="text-[10px] font-mono text-slate-500 bg-slate-900/50 px-2 py-1 rounded-md">ID: {node.id}</span>
      </div>

      <p className={`text-xl leading-relaxed mb-6 font-medium ${textColor}`}>{node.text}</p>

      {node.details && (
        <div className="mb-6">
          <button
            onClick={() => setIsDetailsVisible(!isDetailsVisible)}
            className="w-full text-left px-4 py-2 text-sm font-semibold rounded-lg flex justify-between items-center transition-all bg-slate-900/30 text-slate-400 hover:text-white"
          >
            <span>{isDetailsVisible ? t.node.hideDetails : t.node.showDetails}</span>
          </button>
          {isDetailsVisible && (
            <div className="mt-2 text-sm leading-relaxed p-4 rounded-lg bg-slate-900/40 text-slate-300 border border-white/5 animate-fade-in">
              <p>{node.details}</p>
            </div>
          )}
        </div>
      )}

      {isQuestion ? (
        <div className="mt-8 space-y-6">
          <div className="space-y-4">
            <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-500 px-1">
              <span>{t.node.no}</span>
              <span className={`transition-colors duration-300 ${sliderValue > 55 ? 'text-teal-400' : sliderValue < 45 ? 'text-rose-400' : 'text-slate-300'}`}>
                {getSliderLabel(sliderValue)} ({sliderValue}%)
              </span>
              <span>{t.node.yes}</span>
            </div>
            <input
              type="range" min="0" max="100" value={sliderValue}
              onChange={(e) => setSliderValue(parseInt(e.target.value))}
              className="w-full h-2 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-teal-500"
            />
          </div>
          <button
            onClick={handleNextWithSlider}
            className="w-full sm:w-auto px-10 py-4 bg-teal-600 text-white rounded-xl hover:bg-teal-500 transition-all font-bold shadow-lg"
          >
            {t.node.continue}
          </button>
        </div>
      ) : node.nextNodeId ? (
        <button
          onClick={() => onNavigateDirect(node.nextNodeId)}
          className="w-full sm:w-auto px-10 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-all font-bold shadow-lg"
        >
          {t.node.continue}
        </button>
      ) : isEndNode && (
        <div className={`italic text-slate-400 p-4 rounded-xl bg-slate-900/30 border border-white/5 font-medium`}>
          {t.node.endNodeMessage}
        </div>
      )}

      <div className="mt-12 pt-6 border-t border-slate-700/50 flex flex-wrap gap-3 items-center">
        {canGoBack && (
          <button onClick={onBack} className="px-6 py-2 bg-slate-700 text-slate-200 rounded-lg hover:bg-slate-600 font-semibold border border-slate-600/50">
            {t.node.back}
          </button>
        )}
        <button onClick={onRestart} className="px-6 py-2 bg-amber-600/90 text-white rounded-lg hover:bg-amber-600 font-semibold shadow-md">
          {t.node.restart}
        </button>
        <button onClick={onExport} className="px-6 py-2 border border-slate-600 text-slate-400 rounded-lg hover:bg-slate-700 hover:text-white font-semibold flex items-center">
          {t.node.export}
        </button>
      </div>
    </div>
  );
};

