      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('l', 'mm', 'a4');
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();

      const imgWidth = pdfWidth - 20;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      pdf.setFillColor(2, 6, 23); // bg-slate-950
      pdf.rect(0, 0, pdfWidth, pdfHeight, 'F');
      pdf.addImage(imgData, 'PNG', 10, 10, imgWidth, imgHeight);
      pdf.save(`Diagnostic_Graph_${new Date().toISOString().slice(0, 10)}.pdf`);
    } catch (error) {
      console.error('PDF Export Error:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const renderConnection = (fromId: string, toId: string | undefined) => {
    if (!toId || !nodes[toId]) return null;
    const from = nodes[fromId].position || { x: 0, y: 0 };
    const to = nodes[toId].position || { x: 0, y: 0 };

    const isVisited = historyMap.has(fromId) && (historyMap.has(toId) || activeNodeId === toId);
    const value = historyMap.get(fromId);

    let color = 'stroke-slate-800/30';
    if (isVisited) {
      if (value !== undefined) {
        color = value >= 50 ? 'stroke-teal-500/60' : 'stroke-rose-500/60';
      } else {
