      className="w-full bg-slate-950 rounded-2xl border border-teal-900/30 p-0 mb-8 overflow-hidden relative group h-[400px]"
    >
      <div className="absolute top-4 left-4 z-20 flex flex-col space-y-2">
        <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-500 bg-slate-900/80 px-2 py-1 rounded">
          {t.legend.graphView}
        </h3>
        <div className={`flex space-x-1 ${isExporting ? 'hidden' : ''}`}>
           <button onClick={() => setZoom(z => Math.min(z * 1.2, 3))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700">+</button>
           <button onClick={() => setZoom(z => Math.max(z * 0.8, 0.2))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700">-</button>
           <button onClick={() => {setZoom(1); setOffset({x:0, y:0});}} className="bg-slate-800 hover:bg-slate-700 text-white px-2 h-8 rounded border border-slate-700 text-xs">Reset</button>
           <button 
             onClick={handleExportPDF} 
             disabled={isExporting}
             className="bg-teal-700 hover:bg-teal-600 text-white px-3 h-8 rounded border border-teal-800 text-xs flex items-center space-x-1 disabled:opacity-50"
           >
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M16.5 12 12 16.5m0 0L7.5 12m4.5 4.5V3" />
             </svg>
             <span>{isExporting ? '...' : t.legend.exportPDF}</span>
           </button>
        </div>
      </div>

