interface DiagnosticGraphProps {
  nodes: Record<string, TreeNode>;
  history: HistoryStep[];
  activeNodeId: string;
  onNodeClick: (id: string) => void;
  t: any;
}

const getRankingColor = (value: number | undefined) => {
  if (value === undefined) return 'stroke-slate-700 fill-slate-900/40';

  if (value < 45) {
    return `stroke-rose-500 fill-rose-950/40`;
  } else if (value > 55) {
    return `stroke-teal-500 fill-teal-950/40`;
  }
  return 'stroke-slate-400 fill-slate-800';
};

const DiagnosticGraph: React.FC<DiagnosticGraphProps> = ({ nodes, history, activeNodeId, onNodeClick, t }) => {
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const viewportRef = useRef<HTMLDivElement>(null);
  const fullExportRef = useRef<HTMLDivElement>(null);

  const nodeIds = Object.keys(nodes);

  const historyMap = useMemo(() => {
    const map = new Map<string, number>();
    history.forEach(h => map.set(h.nodeId, h.answerValue ?? 50));
    return map;
  }, [history]);

  // Calculate bounds for the entire network
  const bounds = useMemo(() => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeIds.forEach(id => {
      const pos = nodes[id].position || { x: 500, y: 300 };
      minX = Math.min(minX, pos.x);
      minY = Math.min(minY, pos.y);
      maxX = Math.max(maxX, pos.x);
      maxY = Math.max(maxY, pos.y);
    });
    // Add padding
    const padding = 100;
    return { 
      minX: minX - padding, 
      minY: minY - padding, 
      width: (maxX - minX) + padding * 2, 
      height: (maxY - minY) + padding * 2 
    };
  }, [nodes, nodeIds]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isExporting) return;
    setIsDragging(true);
    dragStart.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || isExporting) return;
    setOffset({
      x: e.clientX - dragStart.current.x,
      y: e.clientY - dragStart.current.y
    });
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleWheel = (e: React.WheelEvent) => {
    if (isExporting) return;
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setZoom(prev => Math.min(Math.max(prev * delta, 0.1), 3));
  };

  const handleExportPNG = async () => {
    if (!fullExportRef.current) return;
    setIsExporting(true);

    // We render a high-res version off-screen
    // Tiny delay to ensure hidden DOM is ready
    await new Promise(resolve => setTimeout(resolve, 200));

    try {
      const canvas = await html2canvas(fullExportRef.current, {
        backgroundColor: '#020617', // Match bg-slate-950
        scale: 3, // Very high quality
        useCORS: true,
        logging: false,
        width: bounds.width,
        height: bounds.height
      });

      const link = document.createElement('a');
      link.download = `Diagnostic_Network_${new Date().toISOString().slice(0, 10)}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('PNG Export Error:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const renderNodesAndLines = (viewBox: string, transformString: string) => (
    <svg 
      width="100%" 
      height="100%" 
      viewBox={viewBox} 
      preserveAspectRatio="xMidYMid slice"
      xmlns="http://www.w3.org/2000/svg"
    >
      <g transform={transformString}>
        {/* Connections */}
        {nodeIds.map(id => {
          const node = nodes[id];
          const targets = [node.yesNodeId, node.noNodeId, node.nextNodeId].filter(Boolean);
          return targets.map(toId => {
            const from = nodes[id].position || { x: 500, y: 300 };
            const to = nodes[toId!].position || { x: 500, y: 300 };
            const isVisited = historyMap.has(id) && (historyMap.has(toId!) || activeNodeId === toId);
            const value = historyMap.get(id);

            let color = 'stroke-slate-800/30';
            if (isVisited) {
              if (value !== undefined) {
                color = value >= 50 ? 'stroke-teal-500/60' : 'stroke-rose-500/60';
              } else {
                color = 'stroke-blue-500/60';
              }
            }
            return (
              <line
                key={`conn-${id}-${toId}`}
                x1={from.x} y1={from.y}
                x2={to.x} y2={to.y}
                className={`transition-all duration-500 ${color}`}
                strokeWidth={isVisited ? 4 : 2}
              />
            );
          });
        })}

        {/* Nodes */}
        {nodeIds.map(id => {
          const node = nodes[id];
          const pos = node.position || { x: 500, y: 300 };
          const isActive = activeNodeId === id;
          const value = historyMap.get(id);

          const colorClasses = getRankingColor(value);
          const size = isActive ? 28 : 20;
          const borderRadius = value !== undefined ? (value > 50 ? 6 : 12) : 100;

          return (
            <g 
              key={`node-${id}`} 
              className="cursor-pointer transition-all duration-300"
              onClick={() => onNodeClick(id)}
            >
              <rect
                x={pos.x - size/2} y={pos.y - size/2}
                width={size} height={size}
                rx={borderRadius}
                className={`${isActive ? 'stroke-teal-400 fill-slate-700' : colorClasses} stroke-2 transition-all duration-300`}
              />
              {isActive && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={35}
                  className="stroke-teal-500/20 fill-none animate-ping"
                />
              )}
              <text
                x={pos.x} y={pos.y + 40}
                textAnchor="middle"
                className={`text-[12px] font-mono fill-slate-500 font-bold pointer-events-none ${isActive ? 'fill-teal-300' : ''}`}
              >
                {id}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );

  return (
    <>
      {/* High-res hidden export element */}
      <div 
        style={{ 
          position: 'absolute', 
          top: '-10000px', 
          left: '-10000px', 
          width: bounds.width, 
          height: bounds.height,
          backgroundColor: '#020617'
        }}
        ref={fullExportRef}
      >
        {renderNodesAndLines(`${bounds.minX} ${bounds.minY} ${bounds.width} ${bounds.height}`, "translate(0,0) scale(1)")}
      </div>

      <div 
        ref={viewportRef}
        className="w-full bg-slate-950 rounded-2xl border border-teal-900/30 p-0 mb-8 overflow-hidden relative group h-[450px]"
      >
        <div className="absolute top-4 left-4 z-20 flex flex-col space-y-2">
          <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-500 bg-slate-900/80 px-2 py-1 rounded">
            {t.legend.graphView}
          </h3>
          <div className={`flex space-x-1 ${isExporting ? 'hidden' : ''}`}>
             <button onClick={() => setZoom(z => Math.min(z * 1.2, 3))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold">+</button>
             <button onClick={() => setZoom(z => Math.max(z * 0.8, 0.1))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold">-</button>
             <button onClick={() => {setZoom(1); setOffset({x:0, y:0});}} className="bg-slate-800 hover:bg-slate-700 text-white px-2 h-8 rounded border border-slate-700 text-xs font-bold uppercase tracking-tighter">Reset</button>
             <button 
