             <button onClick={() => setZoom(z => Math.max(z * 0.8, 0.1))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold">-</button>
             <button onClick={() => {setZoom(1); setOffset({x:0, y:0});}} className="bg-slate-800 hover:bg-slate-700 text-white px-2 h-8 rounded border border-slate-700 text-xs font-bold uppercase tracking-tighter">Reset</button>
             <button 
               onClick={handleExportPNG} 
               disabled={isExporting}
               className="bg-teal-700 hover:bg-teal-600 text-white px-3 h-8 rounded border border-teal-800 text-xs flex items-center space-x-1 disabled:opacity-50 font-bold uppercase tracking-tighter transition-colors"
             >
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M16.5 12 12 16.5m0 0L7.5 12m4.5 4.5V3" />
               </svg>
               <span>{isExporting ? '...' : t.legend.exportPDF}</span>
             </button>
          </div>
        </div>

        <div 
          className="w-full h-full cursor-grab active:cursor-grabbing bg-[radial-gradient(circle_at_center,_rgba(15,23,42,0.5)_0%,_rgba(2,6,23,1)_100%)]"
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={() => { handleMouseUp(); setHoveredNodeId(null); }}
          onWheel={handleWheel}
        >
          {renderNodesAndLines("0 0 1000 600", `translate(${offset.x}, ${offset.y}) scale(${zoom})`, true)}
        </div>
      </div>
    </>
  );
};

export default DiagnosticGraph;

import React, { useState, useRef, useMemo } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';
import html2canvas from 'html2canvas';

interface DiagnosticGraphProps {
  nodes: Record<string, TreeNode>;
  history: HistoryStep[];
  activeNodeId: string;
  onNodeClick: (id: string) => void;
  t: any;
}

// Helper to calculate a smooth color based on value (0-100)
// 0: Rose, 50: Slate, 100: Teal
const getDynamicNodeStyle = (value: number | undefined) => {
  if (value === undefined) {
    return {
      fill: 'rgba(15, 23, 42, 0.4)', // bg-slate-900/40
      stroke: '#334155', // slate-700
      progressColor: '#334155'
    };
  }

  // Linear interpolation for HSL or RGB is easier with a simple map
  // Value 0: Rose-500 (#f43f5e), 50: Slate-400 (#94a3b8), 100: Teal-500 (#14b8a6)
  if (value < 50) {
    // Transition Rose to Slate
    const ratio = value / 50;
    const r = Math.round(244 + (148 - 244) * ratio);
    const g = Math.round(63 + (163 - 63) * ratio);
    const b = Math.round(94 + (184 - 94) * ratio);
    const color = `rgb(${r}, ${g}, ${b})`;
    return { fill: `${color}44`, stroke: color, progressColor: color };
  } else {
    // Transition Slate to Teal
    const ratio = (value - 50) / 50;
    const r = Math.round(148 + (20 - 148) * ratio);
    const g = Math.round(163 + (184 - 163) * ratio);
    const b = Math.round(184 + (166 - 184) * ratio);
    const color = `rgb(${r}, ${g}, ${b})`;
    return { fill: `${color}44`, stroke: color, progressColor: color };
  }
};

const getNodeIcon = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return '❓';
    case NodeType.ALERT:
      return '❗';
    case NodeType.INTERVENTION:
      return '💡';
    case NodeType.OUTCOME:
      return '🏁';
    default:
      return 'ℹ️';
  }
};

const DiagnosticGraph: React.FC<DiagnosticGraphProps> = ({ nodes, history, activeNodeId, onNodeClick, t }) => {
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [hoveredNodeId, setHoveredNodeId] = useState<string | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  const dragStart = useRef({ x: 0, y: 0 });
  const viewportRef = useRef<HTMLDivElement>(null);
  const fullExportRef = useRef<HTMLDivElement>(null);

  const nodeIds = Object.keys(nodes);

  const historyMap = useMemo(() => {
    const map = new Map<string, number>();
    history.forEach(h => map.set(h.nodeId, h.answerValue ?? 50));
    return map;
  }, [history]);

  const focusNodeId = hoveredNodeId || activeNodeId;

  const bounds = useMemo(() => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeIds.forEach(id => {
      const pos = nodes[id].position || { x: 500, y: 300 };
      minX = Math.min(minX, pos.x);
      minY = Math.min(minY, pos.y);
      maxX = Math.max(maxX, pos.x);
      maxY = Math.max(maxY, pos.y);
    });
    const padding = 120;
    return { 
      minX: minX - padding, 
      minY: minY - padding, 
      width: (maxX - minX) + padding * 2, 
      height: (maxY - minY) + padding * 2 
    };
  }, [nodes, nodeIds]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isExporting) return;
    setIsDragging(true);
    dragStart.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isExporting) return;
    if (isDragging) {
      setOffset({
        x: e.clientX - dragStart.current.x,
        y: e.clientY - dragStart.current.y
      });
    }
    setMousePos({ x: e.clientX, y: e.clientY });
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleWheel = (e: React.WheelEvent) => {
    if (isExporting) return;
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setZoom(prev => Math.min(Math.max(prev * delta, 0.1), 3));
  };

  const handleExportPNG = async () => {
    if (!fullExportRef.current) return;
    setIsExporting(true);
    await new Promise(resolve => setTimeout(resolve, 200));
    try {
      const canvas = await html2canvas(fullExportRef.current, {
        backgroundColor: '#020617',
        scale: 3,
        useCORS: true,
        logging: false,
        width: bounds.width,
        height: bounds.height
      });
      const link = document.createElement('a');
      link.download = `Diagnostic_Network_${new Date().toISOString().slice(0, 10)}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('PNG Export Error:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const renderNodesAndLines = (viewBox: string, transformString: string, isInteractive: boolean) => (
    <svg 
      width="100%" 
      height="100%" 
      viewBox={viewBox} 
      preserveAspectRatio="xMidYMid slice"
      xmlns="http://www.w3.org/2000/svg"
    >
      <g transform={transformString}>
        {/* Connections */}
        {nodeIds.map(id => {
          const node = nodes[id];
          const targets = [node.yesNodeId, node.noNodeId, node.nextNodeId].filter(Boolean);
          return targets.map(toId => {
            const from = nodes[id].position || { x: 500, y: 300 };
            const to = nodes[toId!].position || { x: 500, y: 300 };
            const isVisited = historyMap.has(id) && (historyMap.has(toId!) || activeNodeId === toId);
            const value = historyMap.get(id);
            const isFocusRelated = isInteractive && focusNodeId && (id === focusNodeId || toId === focusNodeId);

            let color = 'stroke-slate-800/30';
            if (isVisited) {
              const style = getDynamicNodeStyle(value);
              color = `stroke-[${style.stroke}] opacity-60`;
            }

            const focusColor = isFocusRelated ? 'stroke-teal-400 opacity-80' : '';
            const strokeWidth = isFocusRelated ? 6 : (isVisited ? 4 : 2);

            return (
              <line
                key={`conn-${id}-${toId}`}
                x1={from.x} y1={from.y}
                x2={to.x} y2={to.y}
                style={{ stroke: isFocusRelated ? '#2dd4bf' : (isVisited ? getDynamicNodeStyle(value).stroke : undefined) }}
                className={`transition-all duration-500 ${!isVisited && !isFocusRelated ? 'stroke-slate-800/30' : ''}`}
                strokeWidth={strokeWidth}
                strokeDasharray={isFocusRelated && !isVisited ? "4,4" : "0"}
              />
            );
          });
        })}

        {/* Nodes */}
        {nodeIds.map(id => {
          const node = nodes[id];
          const pos = node.position || { x: 500, y: 300 };
          const isActive = activeNodeId === id;
          const isHovered = hoveredNodeId === id;
          const value = historyMap.get(id);

          const { fill, stroke, progressColor } = getDynamicNodeStyle(value);
          const size = isActive ? 42 : 36;
          const radius = size / 2;
          const borderRadius = value !== undefined ? (value > 50 ? 8 : 16) : 100;

          // Circular progress ring math
          const strokeWidthRing = 3;
          const ringRadius = radius + 4;
          const circumference = 2 * Math.PI * ringRadius;
          const offsetRing = value !== undefined ? circumference - (value / 100) * circumference : circumference;

          return (
            <g 
              key={`node-${id}`} 
              className="cursor-pointer transition-all duration-300"
              onClick={() => onNodeClick(id)}
              onMouseEnter={() => isInteractive && setHoveredNodeId(id)}
              onMouseLeave={() => isInteractive && setHoveredNodeId(null)}
            >
              {/* Progress Ring (Outer) */}
              {value !== undefined && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={ringRadius}
                  fill="none"
                  stroke="rgba(255,255,255,0.05)"
                  strokeWidth={strokeWidthRing}
                />
              )}
              {value !== undefined && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={ringRadius}
                  fill="none"
                  stroke={progressColor}
                  strokeWidth={strokeWidthRing}
                  strokeDasharray={circumference}
                  strokeDashoffset={offsetRing}
                  strokeLinecap="round"
                  transform={`rotate(-90 ${pos.x} ${pos.y})`}
                  className="transition-all duration-1000"
                />
              )}

              {/* Node Body */}
              <rect
                x={pos.x - radius} y={pos.y - radius}
                width={size} height={size}
                rx={borderRadius}
                style={{ fill: fill, stroke: isActive || isHovered ? '#2dd4bf' : stroke }}
                className="stroke-2 transition-all duration-300"
              />

              {/* Node Icon */}
              <text
                x={pos.x} y={pos.y + 1}
                textAnchor="middle"
                dominantBaseline="middle"
                className="text-[16px] pointer-events-none select-none"
              >
                {getNodeIcon(node.type)}
              </text>

              {(isActive || isHovered) && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={size + 12}
                  className="stroke-teal-500/20 fill-none animate-ping"
                />
              )}

              {/* Score label inside node if focused and answered */}
              {(isHovered || isActive) && value !== undefined && (
                <text
                  x={pos.x} y={pos.y - radius - 12}
                  textAnchor="middle"
                  className="text-[10px] font-bold fill-white pointer-events-none select-none drop-shadow-md"
                >
                  {value}%
                </text>
              )}

              {/* Semantic Code Label */}
              <text
                x={pos.x} y={pos.y + radius + 18}
                textAnchor="middle"
                className={`text-[11px] font-mono fill-slate-500 font-black pointer-events-none select-none ${isActive || isHovered ? 'fill-teal-300' : ''}`}
              >
                {id}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );

  return (
    <>
      {/* Tooltip Overlay */}
      {hoveredNodeId && nodes[hoveredNodeId] && (
        <div 
          className="fixed z-[100] pointer-events-none bg-slate-900/95 border border-teal-500/40 rounded-xl p-3 shadow-2xl backdrop-blur-md max-w-xs transition-opacity duration-200"
          style={{
            left: mousePos.x + 15,
            top: mousePos.y + 15,
          }}
        >
          <div className="flex items-center justify-between mb-2 gap-6">
            <span className="text-[10px] font-mono text-teal-400 font-bold uppercase tracking-widest px-1.5 py-0.5 bg-teal-500/10 rounded">
              {nodes[hoveredNodeId].id}
            </span>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-800 px-1.5 py-0.5 rounded uppercase tracking-wider">
              {getNodeIcon(nodes[hoveredNodeId].type)} {t.nodeTypes[nodes[hoveredNodeId].type.toLowerCase()]}
            </span>
          </div>
          <p className="text-sm text-slate-100 font-medium leading-relaxed">
            {nodes[hoveredNodeId].text}
          </p>
          {historyMap.has(hoveredNodeId) && (
             <div className="mt-2 pt-2 border-t border-slate-700/50 flex items-center justify-between">
               <span className="text-[10px] text-slate-500 font-bold uppercase">{t.path.answerHeader}</span>
               <span className={`text-xs font-black ${historyMap.get(hoveredNodeId)! >= 50 ? 'text-teal-400' : 'text-rose-400'}`}>
                 {historyMap.get(hoveredNodeId)}%
               </span>
             </div>
          )}
        </div>
      )}

      <div 
        style={{ 
          position: 'absolute', 
          top: '-10000px', 
          left: '-10000px', 
          width: bounds.width, 
          height: bounds.height,
          backgroundColor: '#020617'
        }}
        ref={fullExportRef}
      >
        {renderNodesAndLines(`${bounds.minX} ${bounds.minY} ${bounds.width} ${bounds.height}`, "translate(0,0) scale(1)", false)}
      </div>

      <div 
        ref={viewportRef}
        className="w-full bg-slate-950 rounded-2xl border border-teal-900/30 p-0 mb-8 overflow-hidden relative group h-[450px]"
      >
        <div className="absolute top-4 left-4 z-20 flex flex-col space-y-2">
          <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-500 bg-slate-900/80 px-2 py-1 rounded">
            {t.legend.graphView}
          </h3>
          <div className={`flex space-x-1 ${isExporting ? 'hidden' : ''}`}>
             <button onClick={() => setZoom(z => Math.min(z * 1.2, 3))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold">+</button>
             <button onClick={() => setZoom(z => Math.max(z * 0.8, 0.1))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold">-</button>
             <button onClick={() => {setZoom(1); setOffset({x:0, y:0});}} className="bg-slate-800 hover:bg-slate-700 text-white px-2 h-8 rounded border border-slate-700 text-xs font-bold uppercase tracking-tighter">Reset</button>
             <button 
               onClick={handleExportPNG} 
               disabled={isExporting}
               className="bg-teal-700 hover:bg-teal-600 text-white px-3 h-8 rounded border border-teal-800 text-xs flex items-center space-x-1 disabled:opacity-50 font-bold uppercase tracking-tighter transition-colors"
             >
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M16.5 12 12 16.5m0 0L7.5 12m4.5 4.5V3" />
               </svg>
               <span>{isExporting ? '...' : t.legend.exportPDF}</span>
             </button>
          </div>
        </div>

        <div 
          className="w-full h-full cursor-grab active:cursor-grabbing bg-[radial-gradient(circle_at_center,_rgba(15,23,42,0.5)_0%,_rgba(2,6,23,1)_100%)]"
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={() => { handleMouseUp(); setHoveredNodeId(null); }}
          onWheel={handleWheel}
        >
          {renderNodesAndLines("0 0 1000 600", `translate(${offset.x}, ${offset.y}) scale(${zoom})`, true)}
        </div>
      </div>
    </>
  );
};

export default DiagnosticGraph;

import React, { useState, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticTreeNodeProps {
  node: TreeNode;
  history: HistoryStep[];
  onNavigateValue: (nodeId: string | undefined, value: number) => void;
  onNavigateDirect: (nodeId: string | undefined) => void;
  onBack: () => void;
  onRestart: () => void;
  onExport: () => void;
  canGoBack: boolean;
  t: any;
}

const getNodeStyling = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return { bgColor: 'bg-slate-800', borderColor: 'border-teal-500/50', textColor: 'text-slate-100', titleColor: 'text-teal-400', accentBg: 'bg-teal-500', icon: '❓', iconBg: 'bg-teal-500/10' };
    case NodeType.ALERT:
      return { bgColor: 'bg-slate-800', borderColor: 'border-rose-500/50', textColor: 'text-rose-50', titleColor: 'text-rose-400', accentBg: 'bg-rose-500', icon: '❗', iconBg: 'bg-rose-500/10' };
    case NodeType.INTERVENTION:
      return { bgColor: 'bg-slate-800', borderColor: 'border-blue-500/50', textColor: 'text-blue-50', titleColor: 'text-blue-400', accentBg: 'bg-blue-500', icon: '💡', iconBg: 'bg-blue-500/10' };
    case NodeType.OUTCOME:
      return { bgColor: 'bg-slate-800', borderColor: 'border-emerald-500/50', textColor: 'text-emerald-50', titleColor: 'text-emerald-400', accentBg: 'bg-emerald-500', icon: '🏁', iconBg: 'bg-emerald-500/10' };
    default:
      return { bgColor: 'bg-slate-800', borderColor: 'border-slate-500/50', textColor: 'text-slate-100', titleColor: 'text-slate-400', accentBg: 'bg-slate-500', icon: 'ℹ️', iconBg: 'bg-slate-500/10' };
  }
};

const DiagnosticTreeNodeComponent: React.FC<DiagnosticTreeNodeProps> = ({
  node,
  history,
  onNavigateValue,
  onNavigateDirect,
  onBack,
  onRestart,
  onExport,
  canGoBack,
  t,
}) => {
  const { bgColor, borderColor, textColor, titleColor, icon, iconBg, accentBg } = getNodeStyling(node.type);
  const [isDetailsVisible, setIsDetailsVisible] = useState(false);
  const [sliderValue, setSliderValue] = useState(50);

  useEffect(() => {
    setIsDetailsVisible(false);
    setSliderValue(50);
  }, [node.id]);

  const isQuestion = node.type === NodeType.QUESTION || node.type === NodeType.REASSESSMENT;
  const isEndNode = !node.yesNodeId && !node.noNodeId && !node.nextNodeId;

  const getRankingData = (val: number) => {
    if (val < 20) return t.ranking.noStrong;
    if (val < 45) return t.ranking.noWeak;
    if (val < 55) return t.ranking.neutral;
    if (val < 80) return t.ranking.yesWeak;
    return t.ranking.yesStrong;
  };

  const handleNextWithSlider = () => {
    const targetId = sliderValue >= 50 ? node.yesNodeId : node.noNodeId;
    onNavigateValue(targetId, sliderValue);
  };

  const currentRanking = getRankingData(sliderValue);

  return (
    <div className={`relative overflow-hidden p-6 rounded-xl border-2 shadow-2xl transition-all ${bgColor} ${borderColor}`}>
      <div className={`absolute top-0 left-0 w-full h-1.5 ${accentBg}`} />

      <div className="flex items-start justify-between mb-4">
        <h2 className={`text-2xl font-bold ${titleColor} flex items-center`}>
          <div className={`p-2 rounded-lg mr-3 flex items-center justify-center ${iconBg}`}>
            <span className="text-2xl">{icon}</span>
          </div>
          {t.nodeTypes[node.type.toLowerCase()]}
        </h2>
        <span className="text-[10px] font-mono text-slate-500 bg-slate-900/50 px-2 py-1 rounded-md">ID: {node.id}</span>
      </div>

      <p className={`text-xl leading-relaxed mb-6 font-medium ${textColor}`}>{node.text}</p>

      {node.details && (
        <div className="mb-6">
          <button
            onClick={() => setIsDetailsVisible(!isDetailsVisible)}
            className="w-full text-left px-4 py-2 text-sm font-semibold rounded-lg flex justify-between items-center transition-all bg-slate-900/30 text-slate-400 hover:text-white"
          >
            <span>{isDetailsVisible ? t.node.hideDetails : t.node.showDetails}</span>
          </button>
          {isDetailsVisible && (
            <div className="mt-2 text-sm leading-relaxed p-4 rounded-lg bg-slate-900/40 text-slate-300 border border-white/5 animate-fade-in">
              <p>{node.details}</p>
            </div>
          )}
        </div>
      )}

      {isQuestion ? (
        <div className="mt-8 space-y-6">
          <div className="space-y-4">
            <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-500 px-1">
              <span>{t.node.no}</span>
              <span className={`transition-colors duration-300 ${sliderValue > 55 ? 'text-teal-400' : sliderValue < 45 ? 'text-rose-400' : 'text-slate-300'}`}>
                {currentRanking.label} ({sliderValue}%)
              </span>
              <span>{t.node.yes}</span>
            </div>
            <input
              type="range" min="0" max="100" value={sliderValue}
              onChange={(e) => setSliderValue(parseInt(e.target.value))}
              className="w-full h-2 bg-slate-900 rounded-lg appearance-none cursor-pointer accent-teal-500"
            />
            {/* Expanded Description Area */}
            <div className="p-4 rounded-xl bg-slate-900/40 border border-white/5 min-h-[4rem] transition-all duration-300">
              <p className="text-sm text-slate-400 italic leading-snug">
                {currentRanking.desc}
              </p>
            </div>
          </div>
          <button
            onClick={handleNextWithSlider}
            className="w-full sm:w-auto px-10 py-4 bg-teal-600 text-white rounded-xl hover:bg-teal-500 transition-all font-bold shadow-lg"
          >
            {t.node.continue}
          </button>
        </div>
      ) : node.nextNodeId ? (
        <button
          onClick={() => onNavigateDirect(node.nextNodeId)}
          className="w-full sm:w-auto px-10 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-500 transition-all font-bold shadow-lg"
        >
          {t.node.continue}
        </button>
      ) : isEndNode && (
        <div className={`italic text-slate-400 p-4 rounded-xl bg-slate-900/30 border border-white/5 font-medium`}>
          {t.node.endNodeMessage}
        </div>
      )}

      <div className="mt-12 pt-6 border-t border-slate-700/50 flex flex-wrap gap-3 items-center">
        {canGoBack && (
          <button onClick={onBack} className="px-6 py-2 bg-slate-700 text-slate-200 rounded-lg hover:bg-slate-600 font-semibold border border-slate-600/50">
            {t.node.back}
          </button>
        )}
        <button onClick={onRestart} className="px-6 py-2 bg-amber-600/90 text-white rounded-lg hover:bg-amber-600 font-semibold shadow-md">
          {t.node.restart}
        </button>
        <button onClick={onExport} className="px-6 py-2 border border-slate-600 text-slate-400 rounded-lg hover:bg-slate-700 hover:text-white font-semibold flex items-center">
          {t.node.export}
        </button>
      </div>
    </div>
  );
};

