import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { TreeNode, HistoryStep, SiteContext } from '../types';
import { GEMINI_MODEL_NAME } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY }); 

export const getAiExplanation = async (userQuery: string, contextNode: TreeNode, lang: 'en' | 'es', siteContext: SiteContext): Promise<string> => {
  const model = GEMINI_MODEL_NAME;
  const responseLanguage = lang === 'es' ? 'Spanish' : 'English';

  const contextLines = [
    `- Node ID: ${contextNode.id}`,
    `- Node Type: ${contextNode.type}`,
    `- Node Text: "${contextNode.text}"`
  ];
  if (contextNode.details) {
    contextLines.push(`- Node Details: "${contextNode.details}"`);
  }

  const landUseStr = Object.entries(siteContext.landUse)
    .filter(([_, active]) => active)
    .map(([key]) => key)
    .join(', ');

  const siteSummary = `
CHARACTERIZATION OF THE INVASION SITE:
- Country: ${siteContext.country || 'Unknown'}
- Specific Place: ${siteContext.specificLocation || 'Not specified'}
- Region: ${siteContext.region || 'Unknown'}
- Involved Species: ${siteContext.species.join(', ') || 'General conifer species'}
- Invasion Stage: ${siteContext.invasionStage}% (0: Introduction, 100: Widespread)
- Land Use: ${landUseStr || 'Not specified'}
- Socio-Economic Impact: ${siteContext.impactLevel}
- Local Observations: ${siteContext.additionalNotes || 'None'}`;

  const systemInstruction = `You are an expert AI assistant specializing in ecological management and governance of invasive species, particularly conifer invasions.
You have access to Google Search to find recent or specific information if needed.
The user is currently navigating a diagnostic tree in the context of the following site:
${siteSummary}

The current step in the diagnostic tree is:
${contextLines.join('\n')}

Please provide a concise, helpful, and relevant explanation or elaboration based on the site context and the diagnostic step.
IMPORTANT: You MUST respond in ${responseLanguage}.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: userQuery,
        config: {
            systemInstruction: systemInstruction,
            tools: [{googleSearch: {}}],
        }
    });

    let aiText = response.text;
    if (aiText) {
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks && groundingChunks.length > 0) {
            const uniqueUris = new Set<string>();
            const sources: string[] = [];
            groundingChunks.forEach(chunk => {
                if (chunk.web && chunk.web.uri && !uniqueUris.has(chunk.web.uri)) {
                    uniqueUris.add(chunk.web.uri);
                    sources.push(`- ${chunk.web.title || 'Untitled'}: ${chunk.web.uri}`);
                }
            });
            const sourcesHeader = lang === 'es' ? "\n\nFuentes de la web:\n" : "\n\nSources from the web:\n";
            if (sources.length > 0) aiText += sourcesHeader + sources.join('\n');
        }
        return aiText;
    }
    return "Format error.";
  } catch (error) {
    return `Error: ${error instanceof Error ? error.message : 'Unknown'}`;
  }
};

export const getAiSummaryFeedback = async (history: HistoryStep[], lang: 'en' | 'es', siteContext: SiteContext): Promise<string> => {
  const model = GEMINI_MODEL_NAME;
  const responseLanguage = lang === 'es' ? 'Spanish' : 'English';

  const pathSummary = history.map((step, i) => `${i+1}. Node ${step.nodeId} (${step.nodeType}): ${step.nodeText} -> Answer: ${step.answerValue ?? 'N/A'}%`).join('\n');

  const landUseStr = Object.entries(siteContext.landUse)
    .filter(([_, active]) => active)
    .map(([key]) => key)
    .join(', ');

  const siteSummary = `
SITE CONTEXT:
- Country: ${siteContext.country}
- Specific Place: ${siteContext.specificLocation}
- Region: ${siteContext.region}
- Species: ${siteContext.species.join(', ')}
- Stage: ${siteContext.invasionStage}%
- Land Use: ${landUseStr}
- Impact: ${siteContext.impactLevel}
- Notes: ${siteContext.additionalNotes}`;

  const systemInstruction = `You are a senior consultant in environmental policy and invasive species management.
The user has completed a diagnostic path for a specific site.
Analyze the path and the site context to provide high-level, actionable feedback.
Offer 3 alternatives or strategic directions tailored to their specific region and invasion stage.
IMPORTANT: You MUST respond in ${responseLanguage}.

SITE CONTEXT:
${siteSummary}

TRAVERSED PATH:
${pathSummary}`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: model,
        contents: "Please provide a summary and strategic alternatives based on my diagnostic path and site characterization.",
        config: { systemInstruction }
    });
    return response.text || "Summary error.";
  } catch (error) {
    return "Error generating summary feedback.";
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { TreeNode, ChatMessage, NodeType, HistoryStep, SiteContext } from './types';
import DiagnosticTreeNodeComponent from './components/DiagnosticTreeNodeComponent';
import ChatPanel from './components/ChatPanel';
import LegendComponent from './components/LegendComponent';
import LanguageSelector from './components/LanguageSelector';
import TutorialModal from './components/TutorialModal';
import DiagnosticGraph from './components/DiagnosticGraph';
import ContextPanel from './components/ContextPanel';
import { getAiExplanation, getAiSummaryFeedback } from './services/geminiService';
import { translationsEN, DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID_EN } from './i18n/en';
import { translationsES, DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID_ES } from './i18n/es';

const TreeIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 2.25H2.25A2.25 2.25 0 0 0 0 4.5v15A2.25 2.25 0 0 0 2.25 21.75h15a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75V6.75A2.25 2.25 0 0 0 16.5 4.5h-6.75a2.25 2.25 0 0 0-2.25 2.25v6.75a2.25 2.25 0 0 0 2.25 2.25h6.75a2.25 2.25 0 0 0 2.25-2.25V13.5m-3-3.75h-1.5m1.5 0v-1.5m0 1.5L12 9m3 3L12 9m0 0L9 12m3-3v1.5m0 0H9m3.75-3.75L12 6.75m0 0L10.125 5.25M12 6.75V5.25m0 1.5L13.875 5.25m-3.75 0h.008v.008h-.008V5.25Z" />
  </svg>
);

type Language = 'en' | 'es';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language | null>(null);
  const [showTutorial, setShowTutorial] = useState(false);
  const [isEvaluationOpen, setIsEvaluationOpen] = useState(false);

  const [currentNodeId, setCurrentNodeId] = useState<string>('');
  const [history, setHistory] = useState<HistoryStep[]>([]);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState<boolean>(false);

  const [siteContext, setSiteContext] = useState<SiteContext>({
    country: '',
    specificLocation: '',
    region: '',
    species: [],
    invasionStage: 10,
    landUse: {
      protectedArea: false,
      forestry: false,
      urbanInterface: false,
      agriculture: false,
    },
    impactLevel: 'low',
    additionalNotes: ''
  });

  const chatRef = useRef<HTMLDivElement>(null);

  const { t, DIAGNOSTIC_TREE_DATA, INITIAL_NODE_ID } = lang === 'es' 
    ? { t: translationsES, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_ES, INITIAL_NODE_ID: INITIAL_NODE_ID_ES }
    : { t: translationsEN, DIAGNOSTIC_TREE_DATA: DIAGNOSTIC_TREE_DATA_EN, INITIAL_NODE_ID: INITIAL_NODE_ID_EN };

  useEffect(() => {
    if (lang) {
      setCurrentNodeId(INITIAL_NODE_ID);
      const hasSeenTutorial = localStorage.getItem('hasSeenTutorial');
      if (!hasSeenTutorial) {
        setShowTutorial(true);
      }
    }
  }, [lang, INITIAL_NODE_ID]);

  const handleSelectLanguage = (selectedLang: Language) => setLang(selectedLang);
  const handleCloseTutorial = () => { setShowTutorial(false); localStorage.setItem('hasSeenTutorial', 'true'); };

  const currentNode = DIAGNOSTIC_TREE_DATA[currentNodeId];

  const onNodeClick = useCallback((id: string) => {
    setCurrentNodeId(id);
    setIsEvaluationOpen(true);
  }, []);

  const navigateWithValue = useCallback((nodeId: string | undefined, val: number) => {
    const currentFullNode = DIAGNOSTIC_TREE_DATA[currentNodeId];
    if (!currentFullNode) return;

    setHistory(prev => [...prev, {
      nodeId: currentNodeId,
      nodeText: currentFullNode.text,
      nodeType: currentFullNode.type,
      answerValue: val
    }]);

    if (!nodeId || !DIAGNOSTIC_TREE_DATA[nodeId]) {
      setIsEvaluationOpen(false);
    } else {
      setCurrentNodeId(nodeId);
    }
  }, [currentNodeId, DIAGNOSTIC_TREE_DATA]);

  const navigateDirect = useCallback((nodeId: string | undefined) => {
    const currentFullNode = DIAGNOSTIC_TREE_DATA[currentNodeId];
    if (!currentFullNode) return;

    setHistory(prev => [...prev, {
      nodeId: currentNodeId,
      nodeText: currentFullNode.text,
      nodeType: currentFullNode.type
    }]);

    if (!nodeId || !DIAGNOSTIC_TREE_DATA[nodeId]) {
      setIsEvaluationOpen(false);
    } else {
      setCurrentNodeId(nodeId);
    }
  }, [currentNodeId, DIAGNOSTIC_TREE_DATA]);

  const handleBack = useCallback(() => {
    if (history.length > 0) {
      const lastStep = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setCurrentNodeId(lastStep.nodeId);
    }
  }, [history]);

  const handleRestart = useCallback(() => { 
    setHistory([]); 
    setCurrentNodeId(INITIAL_NODE_ID); 
    setChatMessages([]);
    setIsEvaluationOpen(false);
  }, [INITIAL_NODE_ID]);

  const handleViewSummary = useCallback(async () => {
    if (history.length === 0) return;
    setIsChatLoading(true);
    chatRef.current?.scrollIntoView({ behavior: 'smooth' });
    try {
      const summaryFeedback = await getAiSummaryFeedback(history, lang || 'en', siteContext);
      setChatMessages(prev => [...prev, {
        id: Date.now().toString() + 'summary',
        sender: 'ai',
        text: summaryFeedback,
        timestamp: new Date(),
      }]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsChatLoading(false);
    }
  }, [history, lang, siteContext]);

  const handleExport = useCallback(() => {
    let content = `${t.appTitle}\n${"=".repeat(20)}\n\n`;
    content += `SITE CHARACTERIZATION:\n`;
    content += `- Country: ${siteContext.country}\n`;
    content += `- Specific Place: ${siteContext.specificLocation}\n`;
    content += `- Region: ${siteContext.region}\n`;
    content += `- Species: ${siteContext.species.join(', ')}\n`;
    content += `- Stage: ${siteContext.invasionStage}%\n`;
    content += `- Impact: ${siteContext.impactLevel}\n\n`;
    content += `DIAGNOSTIC PATH:\n`;
    history.forEach((step, i) => {
      content += `[${i + 1}] (${step.nodeId}) ${step.nodeText}\n`;
      if (step.answerValue !== undefined) content += `    Score: ${step.answerValue}%\n`;
    });
    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Diagnostic_Report_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  }, [history, t, siteContext]);

  const handleUserMessage = useCallback(async (userQuery: string) => {
    if (!userQuery.trim() || !lang) return;
    setChatMessages(prev => [...prev, { id: Date.now().toString() + 'user', sender: 'user', text: userQuery, timestamp: new Date() }]);
    setIsChatLoading(true);
    try {
      const aiResponseText = await getAiExplanation(userQuery, currentNode, lang, siteContext);
      setChatMessages(prev => [...prev, { id: Date.now().toString() + 'ai', sender: 'ai', text: aiResponseText, timestamp: new Date() }]);
    } catch (error) {
      setChatMessages(prev => [...prev, { id: Date.now().toString() + 'error', sender: 'ai', text: t.chat.error, timestamp: new Date() }]);
    } finally { setIsChatLoading(false); }
  }, [currentNode, lang, t, siteContext]);

  if (!lang) return <LanguageSelector onSelectLanguage={handleSelectLanguage} />;

  if (!currentNode) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center text-teal-500">
        Loading Diagnostic data...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-black via-slate-900 to-teal-950 flex flex-col items-center p-4">
      <TutorialModal isOpen={showTutorial} onClose={handleCloseTutorial} t={t} />

      <header className="w-full max-w-5xl mb-6 text-center">
        <div className="flex items-center justify-center space-x-3 mb-2">
           <TreeIcon className="w-12 h-12 text-teal-400" />
          <h1 className="text-4xl font-bold text-stone-100">{t.appTitle}</h1>
        </div>
        <p className="text-lg text-teal-300">{t.appSubtitle}</p>
      </header>

      <div className="w-full max-w-6xl flex flex-col gap-4 relative">

        <ContextPanel 
          context={siteContext} 
          onContextChange={setSiteContext} 
          t={t} 
        />

        <div className="relative w-full h-[600px] bg-slate-950 rounded-2xl border border-teal-900/40 shadow-inner overflow-hidden">
          <DiagnosticGraph 
            nodes={DIAGNOSTIC_TREE_DATA}
            history={history}
            activeNodeId={currentNodeId}
            onNodeClick={onNodeClick}
            t={t}
            showStartInstruction={history.length === 0}
          />

          {/* Evaluation Card Overlay */}
          {isEvaluationOpen && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in">
              <div className="w-full max-w-xl animate-scale-up">
                 <DiagnosticTreeNodeComponent
                    node={currentNode}
                    history={history}
                    onNavigateValue={navigateWithValue}
                    onNavigateDirect={navigateDirect}
                    onBack={handleBack}
                    onRestart={handleRestart}
                    onExport={handleExport}
                    onClose={() => setIsEvaluationOpen(false)}
                    canGoBack={history.length > 0}
                    t={t}
                  />
              </div>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2">
            <ChatPanel messages={chatMessages} onSendMessage={handleUserMessage} onExportChat={() => {}} isLoading={isChatLoading} currentNodeText={currentNode.text} onClose={() => {}} t={t} expanded={true} />
          </div>
          <div className="space-y-4">
             <div className="bg-slate-800/50 backdrop-blur-md p-6 rounded-xl shadow-lg border border-teal-800/30">
               <h3 className="text-lg font-bold text-teal-400 mb-4">{t.path.summary}</h3>
               <div className="max-h-[300px] overflow-y-auto space-y-3 pr-2 scrollbar-thin scrollbar-thumb-teal-900">
                  {history.length === 0 ? (
                    <p className="text-slate-500 italic text-sm">No steps taken yet.</p>
                  ) : (
                    history.map((step, idx) => (
                      <div key={idx} className="p-3 bg-slate-900/50 rounded-lg border border-slate-700/50 flex justify-between items-center text-sm">
                        <span className="text-slate-300 font-medium truncate max-w-[150px]">{step.nodeText}</span>
                        {step.answerValue !== undefined && (
                          <span className="text-teal-400 font-bold whitespace-nowrap">{step.answerValue}%</span>
                        )}
                      </div>
                    ))
                  )}
               </div>
               <button 
                onClick={handleViewSummary} 
                className="w-full mt-6 px-4 py-3 bg-teal-600 hover:bg-teal-500 text-white rounded-xl font-bold shadow-md transition-all disabled:opacity-50" 
                disabled={history.length === 0}
              >
                {t.path.viewSummaryButton}
              </button>
             </div>
             <LegendComponent t={t} />
          </div>
        </div>

      </div>
      <footer className="mt-12 mb-8 text-center text-sm text-teal-600/50">
        <p>&copy; {new Date().getFullYear()} {t.footer}</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';
import html2canvas from 'html2canvas';

interface DiagnosticGraphProps {
  nodes: Record<string, TreeNode>;
  history: HistoryStep[];
  activeNodeId: string;
  onNodeClick: (id: string) => void;
  t: any;
  showStartInstruction?: boolean;
}

const getDynamicNodeStyle = (value: number | undefined) => {
  if (value === undefined) {
    return {
      fill: 'rgba(15, 23, 42, 0.4)',
      stroke: '#334155',
      progressColor: '#334155'
    };
  }

  if (value < 50) {
    const ratio = value / 50;
    const r = Math.round(244 + (148 - 244) * ratio);
    const g = Math.round(63 + (163 - 63) * ratio);
    const b = Math.round(94 + (184 - 94) * ratio);
    const color = `rgb(${r}, ${g}, ${b})`;
    return { fill: `${color}44`, stroke: color, progressColor: color };
  } else {
    const ratio = (value - 50) / 50;
    const r = Math.round(148 + (20 - 148) * ratio);
    const g = Math.round(163 + (184 - 163) * ratio);
    const b = Math.round(184 + (166 - 184) * ratio);
    const color = `rgb(${r}, ${g}, ${b})`;
    return { fill: `${color}44`, stroke: color, progressColor: color };
  }
};

const getNodeIcon = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT: return '❓';
    case NodeType.ALERT: return '❗';
    case NodeType.INTERVENTION: return '💡';
    case NodeType.OUTCOME: return '🏁';
    default: return 'ℹ️';
  }
};

const DiagnosticGraph: React.FC<DiagnosticGraphProps> = ({ nodes, history, activeNodeId, onNodeClick, t, showStartInstruction }) => {
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [hoveredNodeId, setHoveredNodeId] = useState<string | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  const dragStart = useRef({ x: 0, y: 0 });
  const fullExportRef = useRef<HTMLDivElement>(null);

  const nodeIds = Object.keys(nodes);

  const historyMap = useMemo(() => {
    const map = new Map<string, number>();
    history.forEach(h => map.set(h.nodeId, h.answerValue ?? 50));
    return map;
  }, [history]);

  const bounds = useMemo(() => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeIds.forEach(id => {
      const pos = nodes[id].position || { x: 500, y: 300 };
      minX = Math.min(minX, pos.x);
      minY = Math.min(minY, pos.y);
      maxX = Math.max(maxX, pos.x);
      maxY = Math.max(maxY, pos.y);
    });
    const padding = 120;
    return { 
      minX: minX - padding, 
      minY: minY - padding, 
      width: (maxX - minX) + padding * 2, 
      height: (maxY - minY) + padding * 2 
    };
  }, [nodes, nodeIds]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isExporting) return;
    setIsDragging(true);
    dragStart.current = { x: e.clientX - offset.x, y: e.clientY - offset.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isExporting) return;
    if (isDragging) {
      setOffset({
        x: e.clientX - dragStart.current.x,
        y: e.clientY - dragStart.current.y
      });
    }
    setMousePos({ x: e.clientX, y: e.clientY });
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (isExporting) return;
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setZoom(prev => Math.min(Math.max(prev * delta, 0.1), 3));
  };

  const handleExportPNG = async () => {
    if (!fullExportRef.current) return;
    setIsExporting(true);
    await new Promise(resolve => setTimeout(resolve, 200));
    try {
      const canvas = await html2canvas(fullExportRef.current, {
        backgroundColor: '#020617',
        scale: 3,
        useCORS: true,
        logging: false,
        width: bounds.width,
        height: bounds.height
      });
      const link = document.createElement('a');
      link.download = `Diagnostic_Network_${new Date().toISOString().slice(0, 10)}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (error) {
      console.error('PNG Export Error:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const renderNodesAndLines = (viewBox: string, transformString: string, isInteractive: boolean) => (
    <svg 
      width="100%" 
      height="100%" 
      viewBox={viewBox} 
      preserveAspectRatio="xMidYMid slice"
      xmlns="http://www.w3.org/2000/svg"
    >
      <defs>
        <filter id="glow">
          <feGaussianBlur stdDeviation="2.5" result="coloredBlur"/>
          <feMerge>
            <feMergeNode in="coloredBlur"/>
            <feMergeNode in="SourceGraphic"/>
          </feMerge>
        </filter>
      </defs>

      <g transform={transformString}>
        {nodeIds.map(id => {
          const node = nodes[id];
          const targets = [node.yesNodeId, node.noNodeId, node.nextNodeId].filter(Boolean);
          return targets.map(toId => {
            const from = nodes[id].position || { x: 500, y: 300 };
            const to = nodes[toId!].position || { x: 500, y: 300 };
            const isVisited = historyMap.has(id);
            const value = historyMap.get(id);

            return (
              <line
                key={`conn-${id}-${toId}`}
                x1={from.x} y1={from.y}
                x2={to.x} y2={to.y}
                style={{ stroke: isVisited ? getDynamicNodeStyle(value).stroke : '#1e293b' }}
                className={`transition-all duration-500 opacity-30 ${isVisited ? 'opacity-70' : ''}`}
                strokeWidth={isVisited ? 4 : 2}
              />
            );
          });
        })}

        {nodeIds.map(id => {
          const node = nodes[id];
          const pos = node.position || { x: 500, y: 300 };
          const isActive = activeNodeId === id;
          const isHovered = hoveredNodeId === id;
          const value = historyMap.get(id);
          const isStartNode = id === 'Q1' && showStartInstruction;

          const { fill, stroke, progressColor } = getDynamicNodeStyle(value);
          const size = isActive ? 42 : 36;
          const radius = size / 2;

          const circumference = 2 * Math.PI * (radius + 4);
          const offsetRing = value !== undefined ? circumference - (value / 100) * circumference : circumference;

          return (
            <g 
              key={`node-${id}`} 
              className="cursor-pointer transition-all duration-300"
              onClick={() => onNodeClick(id)}
              onMouseEnter={() => isInteractive && setHoveredNodeId(id)}
              onMouseLeave={() => isInteractive && setHoveredNodeId(null)}
            >
              {/* Throb effect for start node */}
              {isStartNode && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={radius + 15}
                  className="fill-teal-500/20 animate-ping"
                />
              )}

              {/* Progress Ring */}
              {value !== undefined && (
                <circle
                  cx={pos.x} cy={pos.y}
                  r={radius + 4}
                  fill="none"
                  stroke={progressColor}
                  strokeWidth={3}
                  strokeDasharray={circumference}
                  strokeDashoffset={offsetRing}
                  strokeLinecap="round"
                  transform={`rotate(-90 ${pos.x} ${pos.y})`}
                />
              )}

              <rect
                x={pos.x - radius} y={pos.y - radius}
                width={size} height={size}
                rx={12}
                style={{ fill, stroke: (isActive || isHovered) ? '#2dd4bf' : stroke }}
                className={`stroke-2 transition-all duration-300 ${isStartNode ? 'filter-glow' : ''}`}
              />

              <text
                x={pos.x} y={pos.y + 1}
                textAnchor="middle"
                dominantBaseline="middle"
                className="text-[16px] pointer-events-none select-none"
              >
                {getNodeIcon(node.type)}
              </text>

              {isStartNode && (
                <g transform={`translate(${pos.x + 25}, ${pos.y - 45})`}>
                  <rect width="120" height="30" rx="8" className="fill-teal-600/90 shadow-lg" />
                  <text x="60" y="20" textAnchor="middle" className="fill-white text-[10px] font-bold uppercase tracking-widest">
                    {t.nodeTypes.question}: Click!
                  </text>
                  <path d="M0 25 L-10 35 L5 25 Z" className="fill-teal-600/90" transform="translate(10, 0)" />
                </g>
              )}

              <text
                x={pos.x} y={pos.y + radius + 18}
                textAnchor="middle"
                className={`text-[10px] font-mono fill-slate-500 font-bold pointer-events-none select-none ${isActive ? 'fill-teal-300' : ''}`}
              >
                {id}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );

  return (
    <div 
      className="w-full h-full relative cursor-grab active:cursor-grabbing bg-[radial-gradient(circle_at_center,_rgba(15,23,42,0.5)_0%,_rgba(2,6,23,1)_100%)]"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={() => setIsDragging(false)}
      onMouseLeave={() => { setIsDragging(false); setHoveredNodeId(null); }}
      onWheel={handleWheel}
    >
      <div className="absolute top-4 left-4 z-10 flex space-x-2">
         <button onClick={() => setZoom(z => Math.min(z * 1.2, 3))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold shadow-lg transition-colors">+</button>
         <button onClick={() => setZoom(z => Math.max(z * 0.8, 0.1))} className="bg-slate-800 hover:bg-slate-700 text-white w-8 h-8 rounded border border-slate-700 font-bold shadow-lg transition-colors">-</button>
         <button onClick={handleExportPNG} className="bg-teal-700 hover:bg-teal-600 text-white px-3 h-8 rounded border border-teal-800 text-[10px] font-bold uppercase tracking-tighter shadow-lg transition-colors">PNG</button>
      </div>

      <div 
        style={{ position: 'absolute', top: '-10000px', width: bounds.width, height: bounds.height }}
        ref={fullExportRef}
      >
        {renderNodesAndLines(`${bounds.minX} ${bounds.minY} ${bounds.width} ${bounds.height}`, "translate(0,0) scale(1)", false)}
      </div>

      {renderNodesAndLines("0 0 1000 600", `translate(${offset.x}, ${offset.y}) scale(${zoom})`, true)}

      {hoveredNodeId && nodes[hoveredNodeId] && (
        <div 
          className="fixed z-[100] pointer-events-none bg-slate-900/95 border border-teal-500/40 rounded-xl p-3 shadow-2xl backdrop-blur-md max-w-xs transition-opacity duration-200"
          style={{ left: mousePos.x + 15, top: mousePos.y + 15 }}
        >
          <p className="text-xs text-slate-100 font-medium leading-relaxed">{nodes[hoveredNodeId].text}</p>
        </div>
      )}
    </div>
  );
};

export default DiagnosticGraph;

import React, { useState, useEffect } from 'react';
import { TreeNode, NodeType, HistoryStep } from '../types';

interface DiagnosticTreeNodeProps {
  node: TreeNode;
  history: HistoryStep[];
  onNavigateValue: (nodeId: string | undefined, value: number) => void;
  onNavigateDirect: (nodeId: string | undefined) => void;
  onBack: () => void;
  onRestart: () => void;
  onExport: () => void;
  onClose: () => void;
  canGoBack: boolean;
  t: any;
}

const getNodeStyling = (type: NodeType) => {
  switch (type) {
    case NodeType.QUESTION:
    case NodeType.REASSESSMENT:
      return { bgColor: 'bg-slate-800', borderColor: 'border-teal-500/50', textColor: 'text-slate-100', titleColor: 'text-teal-400', accentBg: 'bg-teal-500', icon: '❓', iconBg: 'bg-teal-500/10' };
    case NodeType.ALERT:
